quests[9688] = { id = 9688, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Dream", description = "The whelps that you see on this island are the agitated spirits of the green dragonflight. Like me, they are bound to the land, unable to ascend to their final resting place in the Dream.\n\nRecovering the bones of the fallen has settled them somewhat but you must take further action.\n\nDestroy their ethereal manifestations. I cannot leave this place until it is done. They must be released!", completion = "As reprehensible as your task was, it had to be done. Now you must look into the face of evil.", objectives = "Prince Toreth at Wyrmscar Island has asked that you slay 5 Veridian Whelps and 5 Veridian Broodlings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9689] = { id = 9689, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Razormaw", description = "Many of the black dragonflight were slain during the attacks. One of them, a lieutenant of Deathwing himself, still haunts this place. If you look to the heavens, you can see his spectral countenance circling the skies. His hatred is so great that he remains even in death.\n\nTake the bones that you gathered for me earlier to the top of the mountain on this island and place them in the ever-burning pyre. This act should signal Razormaw to descend. When he does, slay his undead form.", progress = "I recommend that you bring allies, {name}.", completion = "How long has it been? A thousand years? Ten-thousand perhaps? You have done me and the memory of my people a great service, {name}. Please accept this item of power as a token of appreciation from Loreth'Aran - in honor of your deeds.", objectives = "Prince Toreth at Wyrmscar Island has asked that you slay Razormaw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9690] = { id = 9690, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Second Trial", description = "Initiate {name}, you have worked hard to master the powers of the Light won by our magisters. You have learned the source of our abilities and of the duties of a Blood Knight.\n\nThe time has come for you to undergo the Second Trial, and contest for status as an adept among the Blood Knights. The trial will be administered by Master Kelerun Bloodmourn at a location north of the city. Travel north through the Ruins of Silvermoon and take the east path immediately before the bridge to Sunstrider Isle.", sourceObjective = "Report to Master Kelerun Bloodmourn.", sourceObjectiveStatus = "unverified-source-field" }
quests[9691] = { id = 9691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Silvermoon", description = "Return to Silvermoon City and report to Knight-Lord Bloodvalor promptly. Your arrival will tell him all he needs to know about the outcome of the trial.\n\nHe will tell you of your remaining tasks on the road to becoming an adept. Hold your head high, {name}. Many undertake this trial, but very few return to tell of their success.You will learn:", sourceObjective = "Return to Knight-Lord Bloodvalor in Silvermoon City.", sourceObjectiveStatus = "unverified-source-field" }
quests[9692] = { id = 9692, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path of the Adept", description = "Before a newly-minted adept can be accepted into the ranks of the Blood Knights, <he/she> must procure the resources  to create our order's distinctive weapon, the blood-tempered ranseur.\n\nYou must also earn the right to wear our order's insignia. When the order was founded, a set number were forged and distributed, so each new adept inherits <his/hers> from a veteran. Your insignia will come from a fallen knight who bravely led an assault on Deatholme.\n\nI have prepared a set of notes to guide you.", objectives = "Bring a Corrupted Kor Gem, a Crate of Bloodforged Ingots, a quantity of Blood of the Wrathful, and a Blood Knight Insignia to Knight-Lord Bloodvalor in Silvermoon City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9693] = { id = 9693, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Argus Means to Me", description = "What does Argus mean to you, {name}? Many draenei probably do not know or remember our home planet. It is there that we split from the man'ari: the twisted demonic reflections of ourselves that were 'gifted' by Sargeras. Or as they call themselves, eredar.\n\nEredar... this word once held meaning.\n\n<Admetius smacks his lips as if to taste the word.>\n\nDisgusting.\n\nLet us not waste anymore time. Find Vindicator Boros to begin your training.", completion = "Ah, {name}... I've heard about you. You're the one that made the Kessel Run in under 15 minutes, right? Bah, probably not.\n\nAre you ready to spill some blood in the name of the Light? For Velen? For Argus?\n\n\n\nI'll slow down.", objectives = "Exarch Admetius at Blood Watch has told you to speak with Vindicator Boros.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9694] = { id = 9694, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood Watch", description = "Blood Watch is one of two forward bases operated by the Hand of Argus. You have already been to the other base, Azure Watch; things are completely different in Bloodmyst. When we first got here, the land was as beautiful as Azuremyst. We even called it Silvergale but now sickness is spreading across the land, worse yet, the blood elves that we were battling on the Exodar survived the crash. This brings me to your assignment: Venture northwest into Bladewood and terminate any blood elves that you find.", completion = "You have returned - and in one piece!\n\nI have some good news, {name}. We have received some new information about the possible location of more survivors. A new crash site has been discovered! When I am done attending to those matters, I will call for you.", objectives = "Vindicator Boros at Blood Watch wants you to slay 10 Sunhawk Spies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9695] = { id = 9695, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sun King's Command", description = "This document looks to be important. Unfortunately, it is written in Thalassian, a language that you cannot understand.\n\nPerhaps Vindicator Boros will know what to do with the letter.", objectives = "Take the Sun King's Command to Vindicator Boros at Blood Watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9696] = { id = 9696, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Translations...", description = "Our chief interrogator, Elysia, is fluent in Thalassian. Take the document to her and see what she has to say.", progress = "I'm a bit busy here, agent {name}. This better be important.", completion = "<Elysia reads from the document.>\n\nIf what this document says is true, the blood elves have opened a portal to the Outland! It would certainly explain their seemingly endless numbers...", objectives = "Take the Sunhawk Missive to Interrogator Elysia at Blood Watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9697] = { id = 9697, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Watcher Leesa'oh", description = "There's important research to be conducted into the ecology of the local creatures, especially the sporelings and bog lords of the marsh.  And trust me, once you get out into the field, you'll find the work to be challenging.\n\nSeek out Watcher Leesa'oh at the Cenarion Watchpost in the western region of the marsh toward the south.  Follow the path west and you will eventually find her.  She can be a bit -- studious -- but don't let that get to you.\n\nOh, and watch out for her cat.", completion = "Oh, good... help finally!  There's just so much to do, and I need to stay here to organize it all.\n\nI hope that you're ready to get your hands dirty.", objectives = "Speak with Watcher Leesa'oh at the Cenarion Watchpost in Zangarmarsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9698] = { id = 9698, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Audience with the Prophet", description = "I need you to deliver the translated documents to Velen personally, {name}. I don't trust that deranged messenger.\n\nExplain to the Prophet that the blood elves are receiving reinforcements from the Outland and that they have a spy amongst the draenei at the Exodar. Velen resides in the Vault of Lights inside the Exodar.\n\nMake haste!", progress = "<Velen smiles.>\n\nGreetings, {name}. I have been expecting you.", completion = "<Velen begins to read the document.>\n\nInteresting... This does indeed explain much.", objectives = "Take the Translated Sunhawk Missive to Prophet Velen at the Exodar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9699] = { id = 9699, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Truth or Fiction", description = "I thank you for the timely delivery, {name}. You are turning out to be one of the Hand's better agents.\n\nIf only we knew who they reported to in Bloodmyst and more importantly, where this sun portal was... They seem to have it tightly guarded - wherever it may be.\n\nWould you be interested in some reconnaissance work?\n\nIf so, take these orders back to Vindicator Boros. He will give you your next mission.", progress = "Well?", completion = "It's a good plan, but a dangerous one. I'm sure you'll be fine.", objectives = "Take Velen's Orders to Vindicator Boros at Blood Watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9700] = { id = 9700, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Shoot Magic Into the Darkness", description = "Velen states that if the blood elves have been opening rifts between this island and the Outland, there will be residue or anomalies left in the areas where the portals have been opened. You must search the island for locations that exhibit or display these anomalies.\n\nBe warned, {name}; some of these anomalies will be creatures from the void itself. Should you find void anomalies, slay them! Report back to me with any new information that you may find. Begin your search to the north, near the Warp Piston.", completion = "How many did you say you saw at the Warp Piston? Just how many times have they opened up this sun portal? This is very bad news...\n\nAlas, you have learned all that I am able to teach you, {name}. Kuros will call for you when it is time.", objectives = "Vindicator Boros at Blood Watch wants you to locate the Sun Portal Site and slay 5 Void Anomalies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9701] = { id = 9701, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Observing the Sporelings", description = "We need to learn all that we can of the sporelings at Sporeggar and their relationship to the creatures around them.  One way to do that is what I'm doing; passive observation while making a note of their interactions.\n\nI need you to head over to the Spawning Glen to the west.  Investigate the whole area and then return to tell me what you saw.", completion = "What?!  The bog lords of Quagg Ridge are EATING the sporelings' pods?  This isn't good!", objectives = "Investigate the Spawning Glen in Zangarmarsh, and then report back to Watcher Leesa'oh at the Cenarion Watchpost in Zangarmarsh with your findings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9702] = { id = 9702, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Question of Gluttony", description = "I was wondering why the bog lords were crossing the road to go to the Spawning Glen - they must be starving for some reason.  This just will not do!\n\nI mean, normally I wouldn't get involved, but if they continue to eat all of the sporeling pods they'll wipe them out!\n\nHere's what we'll do: I'll stay here and you head to the Quagg Ridge to the east and look for dietary clues as to why they're raiding the sporelings.", progress = "Be sure that you collect all of the evidence carefully, {class}!  We're fitting the pieces of a giant puzzle together here.  A mistake on your part could lead us to the wrong conclusions.\n\nThen where would we be in our understanding of Zangarmarsh's ecology?", completion = "This is what you found?  That's odd.  These husked mushroom remains are both unusual and somehow look familiar.\n\nI have to think on this a moment.  Don't go anywhere!", objectives = "Collect 10 pieces of Discarded Nutriment and then return to Watcher Leesa'oh at the Cenarion Watchpost in Zangarmarsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9703] = { id = 9703, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cryo-Core", description = "We have others pursuing leads on the sun portals, {name}. I need you to focus on the task at hand.\n\nBoros has received new reports of another crash site. What we've since discovered is that the crash site is actually the Exodar's cryo-core. This is a pod holding area that houses pods exactly like the ones we draenei crawled out of in Ammen Vale.\n\nThis area also holds medical supplies. Head to the Cryo-Core, directly west of Blood Watch. Search for supplies and search for survivors.", progress = "Was the information accurate?", completion = "Just blood elves? No survivors? This is troubling. I'll need some time to think this through, {name}. Perhaps Aesom or Boros have an assignment for you to complete.", objectives = "Vindicator Kuros at Blood Watch wants you to recover 12 boxes of Medical Supplies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9704] = { id = 9704, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slain by the Wretched", description = "It's hard work being an outrunner between Sunstrider Isle and Falconwing Square.  Tight deadlines, long hours and worst of all... the Wretched!\n\nThe road south goes through the ruins of Silvermoon... the place is crawling with Wretched ready to kill you for a few mana crystals.  Unfortunately, I think that's what happened to the last outrunner we sent with one of Erona's packages.\n\nI see you're eager to prove yourself.  Venture into Dawning Lane and see if you can find any traces of our outrunner.", completion = "The outrunner's belongings have all been stolen with the exception of one package.  It seems to match Alarion's description of Erona's package.", objectives = "Go south into the ruins of Silvermoon and look for the Slain Outrunner in Dawning Lane.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9705] = { id = 9705, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Package Recovery", description = "You take the package and confirm that indeed it comes from Magistrix Erona.  Alarion would probably want you to bring it to her.", progress = "What did you find, {name}?", completion = "By the Sunwell!  That's the third outrunner we've lost this month.\n\nI appreciate your courage in venturing into Dawning Street.  The guards need to keep a closer eye on these blasted Wretched.", objectives = "Return to Outrunner Alarion with Erona's Package.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9706] = { id = 9706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Galaen's Journal - The Fate of Vindicator Saruan", description = "Your hands tremble as you pick up the book. Kuros must be told about this tragedy. Return the book to him.", progress = "What have you got there, {name}? Is that a journal?", completion = "<Kuros' face turns pale as he reads the journal; tears stream down his face.>\n\nSaruan was my master... my teacher... my mentor... I took his place among the Triumvirate only recently - after we had given up searching for him.\n\n<Kuros' face contorts in anger.>\n\nMatis...", objectives = "Take Galaen's Journal to Vindicator Kuros at Blood Watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9707] = { id = 9707, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forging the Weapon", description = "Once again, you have proven yourself worthy before the order and your peers. It is with great pleasure that I bestow upon you the rank of adept, {name}. Prince Kael'thas himself would be proud of you.\n\nAny of us would be honored to fight by your side on the field of battle. Continue to serve as an example for those who aspire to join us. Show neither mercy nor weakness, defend your people and your brothers tirelessly, and hone your mastery of the Light.\n\nNow, claim the weapon befitting your new rank.", objectives = "Take the Crate of Materials to Bemarrin in Silvermoon City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9708] = { id = 9708, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Familiar Fungi", description = "Yes, that's it, I knew I had seen this particular phylum of mushroom elsewhere in the marsh!\n\nTo the north is a place known as the Hewn Bog.  Odd name for the place if you ask me, but I've never been there.  I'll need samples of those mushrooms to confirm my hypothesis.\n\nJust be careful, {class}.  I'd heard that ogres have moved in to the area, so you'll have to get the samples from them.  Could that be why the bog lords are no longer going there for their food?", progress = "Do you have those samples yet?", completion = "We definitely have a match here.  And the presence of the ogres and what they were doing there explains everything.  Now I get why it's called the Hewn Bog, duh!\n\nWe have to do something about this situation, but what?  We can't just wipe out all of those ogres; they have every bit as much a right to be here as any of the other creatures in the marsh!", objectives = "Collect 15 Mushroom Samples and return them to Watcher Leesa'oh at the Cenarion Watchpost in Zangarmarsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9709] = { id = 9709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealing Back the Mushrooms", description = "{class}, I've got an idea.   I want you to head north again, this time into the heart of ogre territory!\n\nNorthwest of the Hewn Bog there is a place named Ango'rosh Stronghold, which sits on a floating island across a large mushroom bridge.\n\nThe ogres must be storing the harvested mushrooms there.  I bet you'll find them all over the place, and probably on the ogres themselves, too!\n\nBring me a sufficient number and I will try to do something about providing the bog lords with a new source of nourishment.", progress = "You have all of the mushrooms that we need to create a new garden for the bog lords?", completion = "These are perfect!  Oh, thank you, {class}!\n\nYou've been ever so careful not to disturb the natural order of things, and we've gathered so much information in such a short amount of time!\n\nNow, let's see if our little plan to grow a new food supply for the bog lords is going to work.", objectives = "Collect 10 Boxes of Mushrooms and return them to Watcher Leesa'oh at the Cenarion Watchpost in Zangarmarsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9710] = { id = 9710, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blood-Tempered Ranseur", description = "I've got everything prepared, {name}. Very soon you will have a weapon befitting your new status.", sourceObjective = "Wait while Bemarrin forges your weapon.", sourceObjectiveStatus = "unverified-source-field" }
quests[9711] = { id = 9711, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Matis the Cruel", description = "Matis will be brought to justice, {name}; and I want you to be the one to find him and bring him back to the Triumvirate.\n\nScour the island for this killer. Should you find him, use this flare gun. When my trackers see the flare, they'll come and assist in capturing Matis. Return to me after he's been captured.", completion = "The Triumvirate has decided to try Matis immediately. You have brought an arch-criminal to justice on this day, young {race}.\n\nYou have performed admirably for two of three; only Aesom remains.", objectives = "Vindicator Kuros at Blood Watch wants you to capture Matis the Cruel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9712] = { id = 9712, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Thalassian Warhorse", description = "You have distinguished yourself in the service of the order, {name}. Your skill in wielding the Light energies granted by Magister Astalor and his fellows has proven you worthy to receive a new kind of knowledge.\n\nWith the Light at your command, it is possible to summon a fearsome warhorse that will serve as your faithful mount.\n\nContinue to serve with dedication and honor, {name}, and even greater boons await you.You will learn:", sourceObjective = "Talk to Knight-Lord Bloodvalor to learn how to summon your Thalassian Warhorse.", sourceObjectiveStatus = "unverified-source-field" }
quests[9713] = { id = 9713, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glowcap Harvesting Enabling Flag" }
quests[9714] = { id = 9714, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring Me Another Shrubbery!", progress = "We can still use more of the sanguine hibiscus from the shamblers, bog giants and underbats of the Underbog at Coilfang Reservoir.  Bring them to me in bunches of five and I will be most grateful.", completion = "These will do nicely, but we can always use more.  Perhaps you will find yourself in the Underbog again soon?" }
quests[9715] = { id = 9715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring Me A Shrubbery!", description = "We must replenish our supply of sanguine hibiscus, which we use for a number of purposes.  They used to grow thick as shrubs, but the lowering of the marsh's water levels means that they can only be found now in the Underbog at Coilfang Reservoir, under Serpent Lake.\n\nIt is said that the shamblers, bog giants, and underbats there consider them a delicacy.  So, if you are to help us, you must retrieve the flowers from them.", progress = "Do you have all of the hibiscus that I asked you to gather?", completion = "These will do nicely, but we can always use more.  Perhaps you will find yourself in the Underbog again soon?", objectives = "Collect 5 Sanguine Hibiscus and return them to Gzhun'tt at Sporeggar in Zangarmarsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9716] = { id = 9716, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disturbance at Umbrafen Lake", description = "We came to Outland expecting to find small pockets of life.  What we discovered in Zangarmarsh was a lush environment with a thriving ecosystem.\n\nOur initial assessment of the area was deceiving, however.  The water levels at the lakes and marshes have consistently been going down since we started taking measurements.\n\nThe impact this could have on the local animal and plant life is disastrous.  Go to Umbrafen Lake, southwest of here, and look for clues related to this water depletion.", completion = "The naga are behind this!  But why?  From what you describe, that steam pump must be part of the cause for the water levels dropping in the marsh!\n\nNo matter - this explains their open hostility towards us.  Let's not waste any time, I need you to perform another task for us.", objectives = "Investigate the cause of the water depletion at Umbrafen Lake. Then return to Ysiel Windsinger at the Cenarion Refuge in Zangarmarsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9717] = { id = 9717, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh, It's On!", description = "While we are a peaceful people, we are at war with the spore giants, whether we like it or not.  And there is a saying amongst us that all is fair in mushrooms and war!\n\nOne of the leaders of the spore giants, Hungerfen, has been tending a very special plant, known as the Underspore, to perfection for millennia.  It would break his spirit if something were to happen to that plant.\n\nTravel to the Underbog in Coilfang Reservoir and steal a frond off of it for us.  Trust me, he'll notice.", progress = "The Underbog is a very dangerous place.  I would not consider you a coward if you were to balk at going there.  I also wouldn't be appreciative of you if you did not return with what I've asked for.", completion = "<The sporeling makes a sound that is vaguely reminiscent of snorting laughter.>\n\nPerfect!  No doubt the morale of the spore giants will be at an all time low once they realize what you've done.\n\nEither that, or they'll be so incensed that they'll attack us again soon.\n\n<T'shu makes a shrugging motion.>", objectives = "Gather an Underspore Frond and return it to T'shu at Sporeggar in Zangarmarsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9718] = { id = 9718, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "As the Crow Flies", description = "We must determine how widespread the naga's activity truly is and react accordingly.\n\nExploring each body of water in Zangarmarsh could be a lengthy undertaking.  If you allow me to, I will use my magic to mold your shape to one more suited to scouting the marsh.\n\nHold this amulet above the balcony near me when you're ready to begin.  I will guide your way back to safety after we're done.", progress = "Hail, {name}.", completion = "It is as I suspected.  The naga have set up pumping stations at all the major lakes in Zangarmarsh. \n\nThey must be stopped if the marsh is to have a future.", objectives = "Ysiel Windsinger wants you to use the Stormcrow Amulet to explore the major lakes in Zangarmarsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9719] = { id = 9719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stalk the Stalker", description = "Historically the greatest danger to my people has been from the marsh walkers.  With the new problems we are facing from spore giants, we cannot afford another attack from our ancient enemies.\n\nYou have proven yourself to be capable, {class}.  Do you think that you'd be able to journey to the Underbog in Coilfang Reservoir and eliminate the great mother of the marsh walkers, known as The Black Stalker?!\n\nBring me her brain as proof.", progress = "You have returned.  Does this mean that The Black Stalker is no more?", completion = "The Black Stalker is dead!  Normally I would not revel in such butchery, but the pain that the great mother and her brood have put my people through over the centuries is unspeakable.\n\nIt is unfortunate that now another of her progeny will transform to replace her, but that will take time and give us some breathing room so that we will not have to worry about the marsh walkers for a while.", objectives = "Bring the Brain of the Black Stalker to Khn'nix at Sporeggar in Zangarmarsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9720] = { id = 9720, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Balance Must Be Preserved", description = "I cannot begin to comprehend why the naga would drain the water out of their own habitat.  What I do understand is a need to put a stop to their operations.\n\nThese seeds carry with them the rage of the earth.  Take them to the steam pumps operated by the naga and use them on their controls.\n\nThe vines that grow from the seeds will be as thick as your arm and as strong as iron.  Go, {name}.  Restore the balance that the naga have upset.", progress = "Is it done, {class}?", completion = "It is done, then.  The marsh has been saved for now.\n\nDon't think for a second that this will be the last we hear of the naga.  We must remain vigilant of our enemy as we continue with our mission in Outland.", objectives = "Ysiel Windsinger wants you to use the Ironvine Seeds on the Steam Pump Controls at Serpent Lake, Umbrafen Lake, Marshlight Lake and the Lagoon. Then return to her at the Cenarion Refuge in Zangarmarsh with any leftover seeds you have.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9721] = { id = 9721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Summons from Lord Solanar", description = "Your dedication to our order and advancement through the ranks has not gone unnoticed. In fact, Lord Solanar Bloodwrath, Lady Liadrin's right hand and a hero in his own right, has asked to speak with you.\n\nThis is a rare honor, {name}. Normally, Lord Solanar leaves the management of the order's rank-and-file to me, but he has taken a personal interest in you. Do not tarry, {name}.", sourceObjective = "Speak with Lord Solanar Bloodwrath in Silvermoon City.", sourceObjectiveStatus = "unverified-source-field" }
quests[9722] = { id = 9722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Master's Path", description = "Within the ranks of our order, there exists an inner circle of elite knights. Members of the circle represent the most dedicated, skilled, and trustworthy of all Blood Knights and are handpicked by the leadership. Most simply know the masters by their thalassian charger mounts.\n\nEach candidate for membership must have a sponsor within the circle and must demonstrate their dedication to the order's central tenets.\n\nI have chosen to sponsor you for standing as a Blood Knight master, if this is your wish.", sourceObjective = "Speak with Lord Solanar Bloodwrath again to accept his offer of sponsorship.", sourceObjectiveStatus = "unverified-source-field" }
quests[9723] = { id = 9723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gesture of Commitment", description = "A Blood Knight's loyalty does not stop at the end of <his/her> blade, {name}. The order asks more of its members than mere drilling and combat. A true knight contributes to all of the order's activities, even the ones that may not seem glorious on the surface.\n\nThis first task is neither combat intensive, nor glorious, but without such contributions, the order would fall apart. I will give you a list of items Magister Astalor Bloodsworn's men require to keep us supplied with Light energy for our magics.", objectives = "Bring 40 Runecloth, 6 Arcanite Bars, 10 Sungrass, 5 Dark Runes, and 150 Gold to Lord Solanar Bloodwrath in Silvermoon City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9724] = { id = 9724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warning the Cenarion Circle", description = "The Cenarion Expedition has become a large organization with a good degree of autonomy.  These events are important enough that we need to warn the Cenarion Circle.\n\nDo not worry, I will not ask you to travel back to Moonglade; we have emissaries as nearby as Hellfire Peninsula.", completion = "The news you bring about the naga activity in Zangarmarsh is dire.  Ysiel was wise in sending word to us.  She hasn't forgotten that the Expedition cannot exist without the Circle's support.", objectives = "Speak to Amythiel Mistwalker at Cenarion Post in Hellfire Peninsula.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9725] = { id = 9725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Demonstration of Loyalty", description = "We Blood Knights are bound to defend Quel'Thalas, {name}. This is a central part of your training. Our enemies are fierce and unrelenting. Silvermoon and its people remain free by our efforts and the support of our allies.\n\nI have received some disturbing reports of a renewed Scourge presence to the southeast of our border with the Eastern Plaguelands. A company of Scourge siege engineers and their equipment appear to be staging for an attack on the Ghostlands. They must not be permitted to succeed.", objectives = "Lord Solanar Bloodwrath in Silvermoon City wants you to destroy 3 Scourge Meat Wagons and kill 15 Scourge Siege Engineers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9726] = { id = 9726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Now That We're Friends...", description = "The naga of the Bloodscale Enclave to the northeast have begun to kill our people.  We cannot allow this to continue, {class}!\n\nWe suggest that you teach them a lesson as proof of our friendship.", completion = "<Gzhun'tt nods to you.>\n\nWe are pleased that you have affirmed our friendship, {name}.  Perhaps the naga heathens will think twice about harassing us in the future now that we have such a powerful ally?", objectives = "Kill 12 Bloodscale Slavedrivers and 6 Bloodscale Enchantresses, and then return to Gzhun'tt at Sporeggar in Zangarmarsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9727] = { id = 9727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Now That We're Still Friends...", description = "Reports have come in that the naga of the Bloodscale Enclave to the northeast continue to kill our people.  We thought that you had dealt with this, {class}!\n\nI suggest that you to teach them a lesson as proof of our continued friendship.", completion = "<Gzhun'tt nods to you.>\n\nWe are pleased that you have reaffirmed our friendship, {name}.  Surely now that you have made our point clear multiple times, their senseless attacks upon our people will cease?", objectives = "Kill 12 Bloodscale Slavedrivers and 6 Bloodscale Enchantresses, and then return to Gzhun'tt at Sporeggar in Zangarmarsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9728] = { id = 9728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Warm Welcome", description = "While the druids from the expedition have made themselves busy studying plants and researching the lakes, I've made it my business to deal with the hostiles in the area.\n\nEver since we set foot in Zangarmarsh, the naga have launched lethal attacks against us without warning.  We've done our best to keep them at bay, but our resources are limited.\n\nI want you to go to the various naga strongholds in Zangarmarsh and show them that we're not to be crossed.  Bring me their claws as proof of your victories.", progress = "It's good to see you again, {name}.  How's your hunt for the naga going?", completion = "Good job, {name}.  You'd do well to shed any feelings of remorse you might harbor.  These naga are vicious creatures - even more so than the Azerothian ones.", objectives = "Warden Hamoot at the Cenarion Refuge wants you to bring him 30 Naga Claws.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9729] = { id = 9729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fhwoor Smash!", description = "Little naga make Fhwoor angry!  Sporelings good friend to Fhwoor, so Fhwoor get naga ark.\n\nWe go into nearby naga village. You help?", progress = "Is Fwhoor alright?  Have you recovered the ark?", completion = "Fhwoor's a good giant.  We saved him from the naga a while ago and he's stayed here helping us with things ever since.\n\nWe can only hope that the naga will take the hint and realize that if we can infiltrate their village and steal their most prized possession, we can do much worse.  Perhaps now they will return to their reservoir and leave us in peace?", objectives = "Escort Fhwoor into the area of the Marshlight steam pump to retrieve the Ark of Ssslith. Bring Fhwoor and the ark back safely and then report back to Gzhun'tt at Sporeggar in Zangarmarsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9730] = { id = 9730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leader of the Darkcrest", description = "A bounty is hereby declared by the Cenarion Expedition on Rajah Haghazed, leader of the Darkcrest naga.  Haghazed was last sighted by Cenarion scouts at the Lagoon, in the central southern region of Zangarmarsh.\n\nThe Darkcrest have been linked to numerous attacks against the Cenarion Expedition and their leader is considered extremely dangerous.\n\nThose seeking to claim the bounty are advised to report to Warden Hamoot.", completion = "I didn't like the naga in Azeroth and I like them less here.  It's a real shame our mission could not remain a peaceful one, but you won't see me shedding tears for dead naga.\n\nHere's your reward for taking care of the Darkcrest leader, {name}.", objectives = "Slay Rajah Haghazed at the Lagoon and return to Warden Hamoot at the Cenarion Refuge in Zangarmarsh for a reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9731] = { id = 9731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drain Schematics", description = "The schematics you've obtained show an underground system of drains and pumps that connect the lakes in the region to Serpent Lake.\n\nIf the schematics are correct, there is a giant drain in the center of Serpent Lake.  Confirm this and bring the news to Cenarion Refuge.", progress = "What news do you bring, {name}?", completion = "The naga have turned Serpent Lake into a giant water sink for the rest of Zangarmarsh.  What could they possibly be doing?\n\nYou've done well in bringing this news to us, {name}.  We will send a team to investigate this drain you've discovered.  I have a different task for you in the meanwhile.", objectives = "Search Serpent Lake for signs of a drain. Return to Ysiel Windsinger at the Cenarion Refuge with news of your discovery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9732] = { id = 9732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Marsh", description = "Return to Ysiel and let her know that help will be extended to her as soon as it is possible.\n\nAffairs in Moonglade and Silithus have kept our members occupied, but we will do our best to send the necessary resources to the Cenarion Refuge.", completion = "You are a welcome sight, {name}.  Matters at the Cenarion Refuge have only gotten worse since you left.", objectives = "Return to Ysiel Windsinger at the Cenarion Refuge in Zangarmarsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9733] = { id = 9733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warning the Cenarion Circle", description = "The Cenarion Expedition has become a large organization with a good degree of autonomy.  These events are important enough that we need to warn the Cenarion Circle.\n\nDo not worry, I will not ask you to travel back to Moonglade; we have emissaries as nearby as Hellfire Peninsula.", sourceObjective = "Speak to Mahuram Stouthoof at Thrallmar in Hellfire Peninsula.The Cenarion Expedition has become a large organization with a good degree of autonomy. These events are important enough that we need to warn the Cenarion Circle.\n\nDo not worry, I will not ask you to travel back to Moonglade; we have emissaries as nearby as Hellfire Peninsula.", sourceObjectiveStatus = "unverified-source-field" }
quests[9734] = { id = 9734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Marsh", description = "Return to Ysiel and let her know that help will be extended to her as soon as it is possible.\n\nAffairs in Moonglade and Silithus have kept our members occupied, but we will do our best to send the necessary resources to the Cenarion Refuge.", sourceObjective = "Return to Ysiel Windsinger at the Cenarion Refuge in Zangarmarsh.", sourceObjectiveStatus = "unverified-source-field" }
quests[9735] = { id = 9735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "True Masters of the Light", description = "A Blood Knight master possesses incredible skill at wielding and weaving the Light in a way that other so-called 'paladins' can never comprehend. It doesn't stop them from despising us for unleashing the Light's true potential.\n\nWe must send them a message and show them that we are not to be trifled with. What I have in mind will be neither brief nor easy, but if you are committed, the first step will be to infiltrate the library wing of the Tyr's Hand Abbey and procure a vial of Tyr's Hand holy water.", objectives = "Lord Solanar Bloodwrath in Silvermoon City wants you to bring him a vial of Tyr's Hand Holy Water.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9736] = { id = 9736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "True Masters of the Light", description = "Now that we have the water, we're going to need a number of reagents in precise quantities. Some of these substances are rare and expensive, {name}, but I have located sources for two.\n\nYou should be able to purchase some arcane catalyst from Zalle, the reagent vendor in one of the shops on the plaza near the Dead Scar. Darlia, the poison merchant near the rogue trainers on Murder Row, stocks crepuscular powder.\n\nTo complete my mixture, I'll also need an azerothian diamond and a pristine black diamond.", objectives = "Lord Solanar Bloodwrath in Silvermoon City wants you to bring him 1 Arcane Catalyst, 1 Crepuscular Powder, 1 Azerothian Diamond, and 1 Pristine Black Diamond.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9737] = { id = 9737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "True Masters of the Light", description = "Ours is the true way of utilizing the Light, {name}. To show others that would call themselves 'paladins' the folly of their ways, I intend to send an unmistakable message.\n\nThe Alonsus Chapel, where the Order of the Silver Hand was founded, seems immune to the destruction of Stratholme. The chapel's eternal flame affords it the Light's protection, but when you use this mixture to extinguish the flame, that protection will be no more. It will burn, and our dominion over the Light will be proven to the world.You will learn:", objectives = "Use the Extinguishing Mixture near the eternal flame in the Alonsus Chapel to remove the Light's protection. Be prepared to fight anyone who may attempt to defend the chapel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9738] = { id = 9738, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost in Action", description = "You have to help me!  We were sent here by Ysiel to investigate the mystery of the steam pumps and why they're being used to drain the water from the marsh.  But my friends split up and went on recklessly without me.\n\nThose four can be such jerks sometimes, but I love them anyway.\n\nThat is why I need you to discover what became of them, though I fear the worst.  Seek them in both the Slave Pens and the Underbog.\n\nThank you, {class}.", completion = "I'm glad that some of my friends yet live, but it breaks my heart to hear of the fate of others.  <sigh>\n\nAt least they died doing what they loved most in life.  You have my eternal gratitude for helping me with this, {name}.\n\nPlease, take one of these as a sign of gratitude.", objectives = "Discover what happened to Earthbinder Rayge, Naturalist Bite, Weeder Greenthumb, and Windcaller Claw. Then, return to Watcher Jhang at Coilfang Reservoir in Zangarmarsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9739] = { id = 9739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sporelings' Plight", description = "You there!  You must help us!\n\nThe fungal giants are devouring all of our spore sacs!  You must do something, or we'll lose our young!\n\nThe spore sacs start out large and become smaller as the air inside them is depleted.  Look for the small, mature spore sacs and save as many of them as you can!", progress = "The spore sacs!  Did you get them?", completion = "You've done it!  You have my people's thanks.\n\nI hope you understand... this is where our young ones come from.  We can't let these beasts devour the sacs!", objectives = "Fahssn at the Spawning Glen wants you to collect 10 Mature Spore Sacs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9740] = { id = 9740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sun Gate", description = "Thanks to you and the work you did, my scouts were able to find the sun gate. The elves keep the portal location mobile so that they can move it at a moment's notice. That's why the site you investigated was empty.\n\nThe strength of such a system is also its greatest weakness. The sun gate is stabilized by portal controllers. If we can take down the controllers, the portal will be ours to destroy. The current sun gate location can be found west of here, south of the Vector Coil. Find it and destroy it!", completion = "Smashing! We've cut off their supply line. Now all that we need to do is finish them off!", objectives = "Vindicator Aesom at Blood Watch wants you to destroy the Sun Gate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9741] = { id = 9741, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Critters of the Void", description = "Aesom sent my squad out on a reconnaissance mission to search for the sun gate a few days ago. Needless to say, we found it...\n\n<Loryi points at Jorli.>\n\nWhatever those fool elves are transporting through that portal is causing void energy to be released. The area is teaming with void critters. \n\nWe must destroy them before they have a chance to grow into void anomalies. You'll find the source of the creatures southwest of here, near the sun gate. Kill them and report back to Aesom when you're done.", completion = "It's a real mess up there, eh? You've done well, {name}. I'll send some anchorites out to help Loryi and Jorli.", objectives = "Kill 12 Void Critters and report to Vindicator Aesom at Blood Watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9742] = { id = 9742, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Spore Sacs", progress = "Have you rescued any more spore sacs, {race}?", completion = "Yes!  You've saved more spore sacs.\n\nYou're different than the other outsiders.  I'll let my people know about your deeds!\n\n<This quest is repeatable up to friendly reputation.>" }
quests[9743] = { id = 9743, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Natural Enemies", description = "Us sporelings and the bog lords have never gotten along well.  In the past, we've managed to keep them at bay with spears and stones.  Lately they seem to have become more aggressive... or more desperate.  They do not fear us or our weapons.\n\nYou are much scarier and better armed than us.  If you were to fight the boglords for us, we'd be forever in your debt!  Bring me their tendrils so I know how many you've killed.", progress = "How's the bog lord slaying going?  Teach those brutes not to come into sporeling territory!", completion = "You made it back alive!  I'll let the other sporelings know about you!  {name}, the giant slayer!", objectives = "Fahssn at the Spawning Glen in Zangarmarsh wants you to bring him 6 Bog Lord Tendrils.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9744] = { id = 9744, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Tendrils!", progress = "You killed many giants, but there are still many more left.  And they're still attacking our spore sacs!", completion = "Unbelievable!  It would take hundreds of sporelings to slay as many giants as you have.  I will make sure to let everyone know of your feats!\n\n<This quest is repeatable up to friendly reputation.>" }
quests[9746] = { id = 9746, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Limits of Physical Exhaustion", description = "Victory is close at hand, {name}. With the discovery of the sun gate, it won't be long until their supply lines are completely closed off. Now is the time to strike at their numbers.\n\nTo the west you will find numerous Sunhawk camps. The Sunhawk pyromancers and defenders occupy the vast majority of the area. Find them, kill them and return to me.", progress = "Their leader can't hide from us forever. We will systematically eliminate every possible hiding place until Sironas is found.", completion = "This will surely soften up their defenses and make them think twice before rushing foolishly into our ranks!", objectives = "Vindicator Aesom at Blood Watch wants you to slay 10 Sunhawk Pyromancers and 10 Sunhawk Defenders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9747] = { id = 9747, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Umbrafen Tribe", description = "The naga are terrible, yes.  But even more terrible are the traitor tribes of Broken and Lost Ones that helped them!\n\nThe worst of all are the Lost Ones of the Umbrafen tribe; they use dark magic to trap and enslave others. They're especially cruel to escaped slaves and would slit my throat if I left the refuge even for a day.\n\nTravel to Umbrafen Village south of here and kill them and their leader, Kataru.  Until then I will fear for my life every single day.", completion = "Thank you, {name}.  I will finally sleep comfortably at night.  Were I not so old and weakened I would deal with my own enemies.\n\nTake this gold.  It is not much, but your kindness cannot go unpaid.", objectives = "Ikeyen at the Cenarion Refuge wants you to travel to Umbrafen Village and slay Kataru, 8 Umbrafen Seers, 6 Umbrafen Witchdoctors and 6 Umbrafen Oracles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9748] = { id = 9748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Don't Drink the Water", description = "Our shaman claim that the elements of water have become greatly agitated by the pollution of the water source. We know that the Exodar's power core is lodged into the mountain to the west. It must be leaking volatile fluids into the water supply! I need you to get me more information.\n\n<Aesom points to a flask and nods.>\n\nYou are to take this flask and follow the beach north until you reach the area where the rivers of Bloodmyst drain into the ocean. Take a sample from that location and return to me.", progress = "Don't drink the water, {name}!", completion = "As I suspected, the water has turned red due to contamination from leaking core fluid.\n\nI hope you didn't swim in any of that contaminated water.", objectives = "Vindicator Aesom at Blood Watch wants you to use the Water Sample Flask to get a Bloodmyst Water Sample.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9749] = { id = 9749, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They're Alive! Maybe...", description = "It was a bloody mess, {name}. We were ambushed by a large pack of these spiders. Their progenitor descended upon us with incredible speed and wrapped us up in cocoons.\n\nAfter we were webbed, she began to lay eggs near us. We were to be food for her young! FOOD!\n\nI managed to cut my way out and escape but I will not leave the others behind. So far I've been unsuccessful in nearing the pass. Would you lend a hand?\n\nDestroy those cocoons! Hopefully some of our team is still alive!", objectives = "Researcher Cornelius has asked that you free 5 Expedition Researchers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9751] = { id = 9751, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bloodcurse Legacy", description = "Last night, Edward Hanes, captain of the ship 'Lost Hope', appeared before me in my tent. The same Edward Hanes that died of scurvy 20 years ago.\n\nThis apparition told me a tale that made my heart tremble. A tale that I need you to hear and a mission that I need you to accomplish. Will you do it? Will you seek out Edward on Wyrmscar Island, northeast of Blood Watch?", completion = "Have you heard of the bloodcurse, landlubber? No, of course you haven't. The bloodcurse is what sunk all these ships. The spoiled, desecrated part of the water here is known as Bloodcursed Reef - a part of the world you never want to visit. I've been here myself for 20 years.\n\nScurvy my foot! I died on these wild shores as food for the dragons... Ah, but that's another story for another time. Right now, we have to help the poor souls that are trapped in that reef.", objectives = "Admiral Odesyus has asked that you find and speak with Captain Edward Hanes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9752] = { id = 9752, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Escape from Umbrafen", description = "You must help me get out of here!\n\nI was gathering herbs nearby when a handful of these little savages abducted me.  I tried to fight them off, but there were too many of them.\n\nHelp me return to the Cenarion Refuge and away from these cruel wretches and their vile magic!", completion = "You rescued one of my druids.  We could never repay you, {name}.\n\nYou have my thanks as well as that of the expedition.", objectives = "Escort Kayra Longmane to the Cenarion Refuge in Zangarmarsh. Report to Ysiel Windsinger when you've completed this task.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9753] = { id = 9753, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What We Know...", description = "We've learned much of our enemies in recent days. The blood elves are led by a being known as Sironas and plot to destroy us. Ultimately, they seek to enslave O'ros and regain control of the Exodar.\n\nLight be praised, we have stopped their supply line by destroying the sun gate. Unfortunately, they continue to use the contaminant of the Vector Coil to poison the land, using the mutagenic properties of the fallout to their advantage.\n\nWith this knowledge, Admetius has devised a plan. Seek him out.", completion = "I am in need of your services, {name}. I have a plan to topple the entire Sunhawk army, but before we can progress, we need to gather some vital information.\n\nWe need to identify the weaknesses in their primary defense. Unfortunately, we have been unable to get close enough to the Vector Coil to gauge their defenses. If we could get the prisoner to talk, we could get the information that we needed to break through the line and destroy the Vector Coil.\n\nYou heard me, I want to blow the damned thing up.", objectives = "Speak to Exarch Admetius at Blood Watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9756] = { id = 9756, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What We Don't Know...", description = "Our attempts at interrogation have failed miserably, {name}. Torture is - of course - out of the question. What we need is a {race} on the inside.\n\nI can cast a spell upon you that would make you appear blood elf and adjust your language. Through subterfuge, we may be able to get the information we need out of the captured agent.\n\nUnder this guise, I want you to get whatever information you can out of the prisoner.\n\nAnd {name}, do not leave Blood Watch while disguised as the spell will fail.", progress = "Do not return until you have succeeded!", completion = "A-ha! Well done, {name}. Well done, indeed. Are you ready to eradicate the blood elf menace from our island forever?", objectives = "Speak to a Captured Sunhawk Agent at Blood Watch and recover Sunhawk Information. Return to Exarch Admetius when the task is complete.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9757] = { id = 9757, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seek Huntress Kella Nightbow", description = "Huntress Kella Nightbow seeks the audience of all eligible hunters.  She is the one to teach you the skill of taming wild beasts, a lesson you should learn above all else at this point in your training.\n\nKella can be found near Valaar's Berth, the docks west of the Exodar.", sourceObjective = "Speak with Huntress Kella Nightbow near Valaar's Berth.Huntress Kella Nightbow seeks the audience of all eligible hunters. She is the one to teach you the skill of taming wild beasts, a lesson you should learn above all else at this point in your training.\n\nKella can be found near Valaar's Berth, the docks west of the Exodar.", sourceObjectiveStatus = "unverified-source-field" }
quests[9758] = { id = 9758, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Arcanist Vandril", description = "Now my friend, if you would be so kind as to return to Arcanist Vandril, I know that he is very anxious to send you out on your first mission here in the Ghostlands.\n\nWe're counting on you, {name}.  Don't let us down.", completion = "Oh good, there you are!  And just in time... there is much to be done!", objectives = "Return to Arcanist Vandril at Tranquillien in the Ghostlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9759] = { id = 9759, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ending Their World", description = "Don't accept this assignment if you value your life. You see that gigantic power core jutting out of the mountain side over yonder? Whoever takes on this burden will need to fight their way through that mountain, battling an army of Sunhawks while protecting me as I rig the core up for demolition. Sironas the eredar is somewhere up there as well.\n\nI won't think less of you if you just walk away, {name}.\n\nBut maybe you're the one - the one to destroy the Vector Coil and take down Sironas. Well, are you?", completion = "You have saved the whole of Bloodmyst and Azuremyst, securing the {race} way of life on Azeroth, {name}! For this, there can be no amount of thanks, no reward, nothing large enough in scope to truly express our appreciation.\n\nYet, there are still so many that were left behind on Draenor who cannot be here for this historic event. You must find your way back. Find your way back to the Outland, Hero of Argus. Bring our people home. Home to the land that you saved. Home to Azeroth...", objectives = "Follow and protect Demolitionist Legoso as he attempts to destroy the Vector Coil and slay Sironas. Return to Exarch Admetius at Blood Watch should you complete the mission.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9760] = { id = 9760, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vindicator's Rest", description = "I would not ask you to single-handedly bear the burden of destroying the Vector Coil and slaying Sironas, {name}; however, I believe that you can be of some help in clearing the way for others that might take on such a dangerous assignment.\n\nTake the road going north out of Blood Watch and follow it until you get to the fork. Once there, take the left road and follow it until you see Vindicator's Rest - it will be slightly west of the road itself. Corin will be waiting for you.", completion = "Perhaps you will be the one to deliver our people into a new age of prosperity and peace.", objectives = "Speak with Vindicator Corin at Vindicator's Rest on Bloodmyst Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9761] = { id = 9761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clearing the Way", description = "Only the most battle hardened, noble and positively fearless will submit to Legoso's mission. The exarch will not order any agent of the Hand to take on the task of destroying the Vector Coil and dispatching Sironas. He refuses to send any draenei to their death - which is what the mission is: suicide...\n\n<Corin sighs.>\n\nMy job is to soften up the Sunhawk defenses. You are to slay Sunhawks near the Vector Coil and keep the path clear for our champion - whoever that may be.", completion = "Hopefully a hero arrives before they are able to call forth reinforcements to guard the area you just secured.", objectives = "Vindicator Corin at Vindicator's Rest wants you to slay 8 Sunhawk Saboteurs and 8 Sunhawk Agents.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9762] = { id = 9762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Unwritten Prophecy", objectives = "These islands will serve as the home to thousands. Most of these people will remain here their entire lives. If you so desired, you could do the same. But that's not what you want, is it, {name}?\n\n\n\nYou will do many more great things before you pass. You must embrace your destiny and meet it head on!\n\nBefore you leave, I present you with two gifts: This tabard is worn by only the most revered of the Hand of Argus and this signet ring worn by our wisest sages. Wear them both with pride, {name}.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9763] = { id = 9763, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warlord's Hideout", description = "There are benefits to hiding very, very quietly at the entrance of your enemy's hideout.\n\nJust hours ago I saw a group of naga go through the stone archway on the second tunnel from the left.  I'm not well versed in their language, yet I clearly understood one word: Kalithresh.\n\nThat must be the entrance to the steam vaults, where Warlord Kalithresh has been commanding his troops from.  You must find him and stop him.  I am too weak to be of any assistance.", completion = "Our biggest enemy in the region is finally dead.  You've done the expedition a great favor, {name}.\n\nWe shall be forever in your debt.", objectives = "Watcher Jhang wants you to find and slay Warlord Kalithresh inside Coilfang Reservoir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9764] = { id = 9764, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orders from Lady Vashj", description = "This letter contains detailed orders to the Coilfang naga operating the steam vaults.  It warns of the arrival of Cenarion druids into the region and orders them to be slain on sight.  The rate of water redirection from other lakes into Coilfang Reservoir is to be doubled.  The orders bear the seal of the infamous Lady Vashj.\n\nThis letter would be of great interest to the druids of the Cenarion Expedition.  Take it to their leader, Ysiel Windsinger.", progress = "What's that you have there, {name}?", completion = "Vashj!\n\nThis is much more than we bargained for.  Our small victories here and there against the naga mean nothing.\n\nIf Lady Vashj is involved in this, then forces much greater than us are at work. \n\nYou've done well in bringing this to us, {name}.  Now, we must prepare for war.", objectives = "Deliver the Orders from Lady Vashj to Ysiel Windsinger at the Cenarion Refuge in Zangarmarsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9765] = { id = 9765, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preparing for War", description = "The Cenarion Expedition began as a peaceful venture, yet we now face the prospect of all out war with the naga.\n\nWe have many among us who are willing to fight but are ill equipped.  Bring me the naga's own weapons so that we may reforge them into glaives and arrowheads.\n\nOnly the best armaments will have materials useful to us, {name}.  You will have to seek out the naga of Coilfang Reservoir.", progress = "Have you obtained the armaments I seek, {name}?", completion = "These will do perfectly, {name}.  Bring any more armaments you find.  Our need is great and our resources are scarce.", objectives = "Obtain Coilfang Armaments from naga at Coilfang Reservoir and return them to Ysiel Windsinger at the Cenarion Refuge in Zangarmarsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9766] = { id = 9766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coilfang Armaments", progress = "We will forge the naga's own steel into weapons to use against them.  Bring me all the armaments you manage to salvage from Coilfang Reservoir.", completion = "Excellent work, {name}.  The naga will learn not to underestimate us." }
quests[9767] = { id = 9767, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Know Your Enemy", description = "Defeating an enemy requires more than superior power or numbers.  Victory often hinges on knowledge of an opponent's weaknesses, the anticipation of their plans or the recognition of a behavior pattern.\n\nWe know much about the naga, yet much of their magical practices remain foreign to us.\n\nI seek to learn of the Hydromancy used by the naga of Coilfang Reservoir.  Bring me one of their spellbooks so I may learn more about it.", objectives = "Obtain a Coilfang Spellbook from the naga inside of Coilfang Reservoir and bring it to Ashyen at the Cenarion Refuge in Zangarmarsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9768] = { id = 9768, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coilfang Spellbooks" }
quests[9769] = { id = 9769, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "There's No Explanation for Fashion", description = "<Magasha chuckles softly to herself.>\n\nI bet if they knew they were wearing bug parts, the fashion trend would end very quickly.\n\nWe first started killing the bugs 'round here 'cause they were getting in the way of our construction. Some enterprising merchant stops here, spends the night, and next thing you know he's buyin' up all the bug wings we have!\n\nSays he makes clothes out of 'em. I be stickin' to my armor, thanks. But if you gather the wings of any of the fireflies, I'll gladly buy 'em.", progress = "What's that, there? Been bitten by the wing bug, have ya?\n\n<Magasha chuckles at her own joke.>", completion = "These be fine ones, {name}. Here's your payment.\n\n\n\nNope, not my thing, but who'm I to complain?\n\n\n\nCoin speaks.", objectives = "Bring 8 Diaphanous Wings from any species of Zangarmarsh fireflies to Magasha in Swamprat Post.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9770] = { id = 9770, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Menacing Marshfangs", description = "Sometimes I wish Denjai had sent a shaman with us, or at least given us a totem to keep the marshfang rippers at bay.\n\nThe whole place is crawling with the pests! It's just not right. Shouldn't something be eating these despicable things?\n\nWe've all been taking turns playing exterminator. You showed up at just the right time, {name}. Congratulations! Now get out there and mop up some marshfangs!", completion = "Had your fill already?\n\n<Reavij laughs.>\n\nThere's a reason why our visitors don't stay long.\n\nIf I had a choice, I'd find a more agreeable spot for the post, but I'll take marshfangs over Denjai's temper any day.", objectives = "Reavij at Swamprat Post wants you to kill 10 Marshfang Rippers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9771] = { id = 9771, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Searching for Scout Jyoba", description = "Now that you're familiar with the terrain, I'd like to ask your help with something else. The Dead Mire, we've taken to calling the area to the northwest, is an eerie place. No one has ever reported seeing anything alive there, but they didn't stay for very long, either.\n\nScout Jyoba volunteered to investigate the area and report on his findings. He left the post three days ago and hasn't returned. It's not like him to be gone that long without sending some kind of report. Will you search for him, {name}?", completion = "The battered corpse matches Zurai's description perfectly. Whatever killed the scout appears to have taken him by surprise, as his weapon is sheathed and the contents of a small inkwell stain the nearby ground.", objectives = "Search for Scout Jyoba at the Dead Mire in Zangarmarsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9772] = { id = 9772, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jyoba's Report", description = "Flecks of withered fungus dot the body of Scout Jyoba. Whatever killed him must've been made of the same dying fungus as the giant wilting mushrooms of the Dead Mire. Perhaps one of the withered giants caught him by surprise as he sat writing his report.\n\nWithout the text of the report, it's nearly impossible to tell what the scout discovered. If the report can be found, it should be returned to Zurai.", progress = "You're back, but Jyoba's not with you. What became of him?", completion = "<Zurai accepts the report from you and glances over it.>\n\nMuch of this is information we already know. Everything in the area seems to be dried or wilting, but here's something new.\n\nHe says the fungal giants seem to have gone berserk from the lack of moisture. From your description, that must be what killed him.\n\nI'll instruct my men to avoid the area. We can't afford any more casualties.", objectives = "Retrieve Scout Jyoba's Report from the Withered Giants and return it to Zurai at Swamprat Post.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9773] = { id = 9773, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No More Mushrooms!", description = "Mushroom soup, mushroom stew, mushroom sauce!\n\nMushroom, mushroom, mushroom! It's all there is to eat around here. If you say you're hungry, the cook hands you an axe and tells you to go chop down your dinner!\n\nWell, I'm tired of mushrooms. I've seen fish in the lakes around here. Sure, they look like a nasty piece of work, but they've got to be better than mushrooms!\n\nHow much will it cost me to hire you to bring me my first decent meal in weeks?", progress = "Tell me you haven't come back empty-handed. {name}.", completion = "Finally, a break from the monotony of mushrooms! If you didn't smell like fish, I'd hug you.\n\nLet's see how jealous the others get when they smell the meat cooking over the fire.", objectives = "Gather 8 Eel Filets from Umbrafen Eels and bring them to Magasha at Swamprat Post.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9774] = { id = 9774, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thick Hydra Scales", description = "Reavij was wise to bring leather armor. This swamp will render my mail useless before long.\n\nI've been replacing the scales bit by bit as I'm able. The hydra in the marsh have thick, protective scales that stand up well to the dampness of their home.\n\nFinding suitable ones is a tedious process, though. All too often, the best scales are torn or worn too thin for use in armor. Bring me any good ones that you might get from the hydra in the larger lakes.", progress = "I see you smirking. Yes, my armor's going to look a bit odd until I've replaced all the old metal, but it's better this than unprotected.", completion = "Thank you, {name}. Every little bit helps.\n\nI've still got a long way to go, but let's face it, what else am I going to do between patrols?", objectives = "Zurai at Swamprat Post wants you to bring him 12 Thick Hydra Scales.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9775] = { id = 9775, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Shadow Hunter Denjai", description = "Shadow Hunter Denjai will no doubt expect to receive a report about my progress in establishing our outpost. I've prepared a short summary of what we've accomplished here already, but with the loss of Scout Jyoba, I can't spare a runner to take the report to Denjai's base of Zabra'jin to the west.\n\nIf you're headed that way, would you mind bringing this to him? Shadow Hunter Denjai can be a little intimidating at first, but once you get used to him, he's not so bad.", progress = "You don't look like one of my men. Speak your piece, {race}.", completion = "Why didn't you say you had a report from Zurai? I've been waiting to hear from him.\n\nI sent him out there to give us a presence on the eastern border, not sit on his hands. Let's see what he has to say.", objectives = "Bring Zurai's Report to Shadow Hunter Denjai at Zabra'jin in Zangarmarsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9776] = { id = 9776, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Orebor Harborage", description = "As you know, many of Telredor's inhabitants are refugees from the war that decimated the draenei. It is my goal to maintain Telredor as a safe haven for all of our allies in this struggle. There are some who desire to join us, but feel they are not yet ready.\n\nWe owe them whatever help we can provide, {name}. A group of Broken under the leadership of Ikuti have taken shelter in the ruins of an old temple to the northwest of Serpent Lake. Seek them out and extend your hand in friendship to them.", completion = "If Anchorite Ahuurn counts you a friend, then you may prove trustworthy. Please forgive my wariness, {race}, but it is often all that stands between my people and death. You are welcome to shelter among us, and perhaps our mutual trust will grow.", objectives = "Speak to Ikuti at the Orebor Harborage in Zangarmarsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9777] = { id = 9777, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fulgor Spores", description = "There is little in this swamp that will burn, {race}, so we must resort to other means for lighting Telredor. Many of the creatures and plants in the marsh emit a soft glow.\n\nIt's difficult and cruel to confine the glowing creatures, so we've turned to a species of mushroom for our light source.\n\nWe pick and cultivate the fulgor mushroom here, but our needs require us to gather new crops occasionally. The small green mushrooms often grow at the base of larger ones near Telredor.", progress = "From the looks of things, we'll need to replenish our spores soon.", completion = "These are good spores and they should keep us going for quite some time. Thank you for helping us to replenish our supplies, {name}.", objectives = "Bring 6 Fulgor Spores to Ruam at Telredor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9778] = { id = 9778, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warden Hamoot", description = "Before you leave Cenarion Refuge, make sure you speak with Warden Hamoot.  He's in charge of the expedition's security.\n\nHe would never forgive me if I didn't send a seasoned adventurer like you his way.", completion = "Ysiel sent you?  Of course I can use someone like you!  We're always in need of a little muscle.", objectives = "Report to Warden Hamoot at the Cenarion Refuge in Zangarmarsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9779] = { id = 9779, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Intercepting the Message", description = "It is good to see you again, {name}. I have a quandary that you might be able to solve.\n\nOur agents situated behind Sunhawk lines have reported seeing Sunhawk soldiers parsing an unusual document.\n\nUnfortunately, we have been unsuccessful in acquiring a copy of the document for ourselves. I need you to go out in the field and try to recover the document. I am certain that if you apply enough pressure, a Sunhawk agent will turn over the information we seek. I leave the use of force to your discretion.", progress = "Back so soon? Have you found the missive?", completion = "<Vindicator Boros eyes the document.>\n\nThis is in Thalassian. Fortunately, I know just the person that can translate it...", objectives = "Kill Sunhawk elves until you find the Sunhawk Missive, then return it to Vindicator Boros at Blood Watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9780] = { id = 9780, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Umbrafen Eel Filets", description = "It's good to see another fresh face here. When Haalrun and I first came to Telredor, we were the only outsiders, but that seems like a lifetime ago.\n\nStill, we try to welcome newcomers and ensure that there's always enough food and supplies. We can never fully repay the kindness of the Telredor anchorites, but we can follow their example and extend it to others.\n\nIf you would like to help, the nearby lakes are populated with a fish called the Umbrafen eel, whose meat is a staple of our diet.", progress = "Have you any fish to contribute to our stores?", completion = "Thank you for your help, {name}. Your generosity will not be forgotten.", objectives = "Noraani at Telredor wants you to bring her 8 Eel Filets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9781] = { id = 9781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Too Many Mouths to Feed", description = "On my last hunting trip, I caught sight of a new outpost being built by a group of trolls. No doubt they've begun hunting these lands, too.\n\nIf they establish a permanent presence out here, the competition for food will be fierce. We cannot take direct action against them without provocation, but we can remove some of the natural competition for food.\n\nFor each mire hydra you kill, that's three fewer mouths to feed!", completion = "Well done. That should ease the demand on the food supply around here for the immediate future, although we're going to need to find new sources of food. Fish and mushrooms suffice, but variety can never be underestimated.", objectives = "Kill 10 Mire Hydra and return to Haalrun at Telredor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9782] = { id = 9782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dead Mire", description = "I have lived among the anchorites of Telredor for some time, {name}, and in that time I've come to know the marsh quite well. Recently, I've started to notice a disturbing change in the land to the northeast.\n\nVirtually all life there has begun to wither and die, seemingly without explanation. I have a few ideas as to what might be happening, but they are little more than speculation. If you were to bring me a sample of the soil in that area, I may be able to get to the bottom of this mystery.", progress = "Were you able to get a sample of the soil in the Dead Mire?", completion = "Hmm... The soil seems to be depleted, so it can't be the cause of the problem, as I'd thought. What's the common link here? Why is everything suddenly dying?", objectives = "Bring a Dead Mire Soil Sample to Vindicator Idaar at Telredor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9783] = { id = 9783, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Unnatural Drought", description = "The soil sample you brought me is nearly devoid of moisture, {name}. If the soil itself is losing moisture, then the creatures that live in the Dead Mire must be suffering terribly.\n\nI've seen what happens when the region's fungal giants begin to wither and die. The pain drives them mad, causing them to attack anything in their path.\n\nThese creatures have no idea what's happening to them. They're beyond our ability to save, so the best we can do is to end their suffering.", completion = "Thank you for helping with this difficult task, {name}. Our work in the Dead Mire is not yet done, but now our efforts will focus on doing what we can to restore balance to the area.", objectives = "Vindicator Idaar at Telredor wants you to kill 12 Withered Giants.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9784] = { id = 9784, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Identify Plant Parts", progress = "I could still use some more plant parts.  With the lakes losing their water, I've a feeling the number of invasive species is on the rise.  I need more numbers to back up my theory, however.", completion = "Excellent.  Keep bringing me more plant parts if you find any.\n\n<This quest is repeatable up to Honored reputation.>" }
quests[9785] = { id = 9785, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blessings of the Ancients", description = "You've earned the trust of the Cenarion Expedition, {name}.  It is time you spoke to the ancients allied with our cause, Ashyen and Keleth, and asked for their blessing.\n\nCarrying the mark of an ancient will fill you with great power.  These boons will become more powerful as your renown among us increases.\n\nGo, {name}, and ask the ancients for their blessing.", completion = "You've returned.  Did you receive the ancients' blessings?", objectives = "Windcaller Blackhoof wants you to speak to the ancients Ashyen and Keleth at Cenarion Refuge and obtain their blessings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9786] = { id = 9786, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Boha'mu Ruins", description = "Before my people were decimated by the orcs, Telredor served as a retreat for draenei anchorites and spiritualists. A small order of anchorites and vindicators maintained a number of shrines in this region.\n\nDuring the war, we lost contact with the anchorites assigned to the shrines, particularly the Boha'mu temple to the southwest. I've heard reports that a tribe of Lost Ones has settled in the area and may even be using the ruins. Visit the Boha'mu Ruins and tell me of what you find there.", progress = "Have you examined the Boha'mu Ruins? Can you imagine what they were like in their full splendor?", completion = "So, the Feralfen Lost Ones have taken over the ruins? Most intriguing. They must remember something of their heritage and the significance of the site. We must learn more, {name}. This temple could hold the key to redeeming the Lost Ones and reuniting the many threads of draenei.", objectives = "Anchorite Ahuurn at Telredor wants you to explore the Boha'mu Ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9787] = { id = 9787, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Idols of the Feralfen", description = "From what you've told me about your observations at the Boha'mu Ruins, it seems this tribe of Lost Ones has reverted to the worship of animal spirits. Before we can approach them, we must know more of their beliefs.\n\nReturn to Feralfen Village and discreetly gather some of their idols so that I may study them. Try to avoid angering them, {name}, as it may hurt our chances of making contact with them.", progress = "Do you have the idols?", completion = "These should be more than sufficient, {name}. They seem to be fixated on birds, which is odd, because there aren't any bird species native to Zangarmarsh. What could this mean?\n\nCould they have encountered the arakkoa? To a shamanistic people, they might seem like the embodiment of a powerful bird spirit.", objectives = "Gather 6 Feralfen Idols and return them to Anchorite Ahuurn at Telredor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9788] = { id = 9788, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Damp, Dark Place", description = "Soon after I escaped the Umbrafen tribe, I holed up in a cave south of their village.  Little did I know that the cave was being fought over by marsh beasts and spore men!\n\nI had to leave in a hurry and left behind a box containing my only worldly possessions.\n\nAfter managing to sneak out of Umbrafen with my belongings it was terrible irony that I would lose them so soon after.  If you're willing to bring them back to me I'll give you one of my very own personal items.  What do you say, {name}?", progress = "Did you find my belongings, {name}?  The cave is not far from Umbrafen, near the border with Nagrand.", completion = "My things!  They're all here!\n\nI thank you, {name}.  As promised, I'll let you pick one of the items for yourself.  I don't have much to offer, but my people have always shared what little we have.", objectives = "Look for Ikeyen's Belongings inside a cave south of Umbrafen. Return them to Ikeyen at Cenarion Refuge in Zangarmarsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9789] = { id = 9789, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clefthoof Mastery", description = "You want to earn a place in this safari?  You'll have to prove yourself.\n\nI don't care what you've hunted before, you haven't hunted until you hunt what we hunt here.  Start with the clefthoof if you're <man/tough> enough.\n\nI know that I've seen them in the immediate area around the safari and also close by to the south.", completion = "A fair start.  But that's just the beginning.\n\nThe lesser clefthoof prove nothing.  Let's move you up to a bigger challenge.", objectives = "Hunt down 12 Clefthoof and return to Hemet Nesingwary at Nesingwary's Safari in Nagrand to prove yourself.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9790] = { id = 9790, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diaphanous Wings", description = "Living in such a remote location has taught us to make use of everything available. Of course, you have to learn to stop thinking about where some of these materials come from first.\n\nI've found that the wings of the umbraglow stingers are very helpful for waterproofing. They're strong, thin, and flexible.\n\n<Haalrun chuckles.>\n\nI see the look on your face. Like I said, it takes time to get used to the idea. If you're going to be out and about, would you mind bringing me some of the wings?", progress = "Did you manage to gather any diaphanous wings?", completion = "Thank you, {name}.\n\n\n\nAt least you don't have to clean them. That's the worst job of the lot, but once it's done, you'd never know they were attached to a giant insect.", objectives = "Haalrun at Telredor wants you to bring him 8 Diaphanous Wings from any of the firefly species in Zangarmarsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9791] = { id = 9791, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Menacing Marshfangs", description = "During the orcs' war against my people, gatherers rarely left Telredor for fear of being attacked or captured. Now, we venture out more often, but the marsh is no less perilous.\n\nIt seems that the nether rays have grown bolder in recent months. I don't know if it has something to do with more competition for their normal prey, but they've been attacking our foraging parties on a regular basis. If we can thin their ranks in the area around Telredor, perhaps they would learn to leave us alone.", completion = "Thank you for your help in clearing out some of the marshfang rippers, {name}. If they had any intelligence, perhaps they'd learn that it's best to live and let live.\n\n\n\nGiant, overgrown bugs with intelligence. I wonder what that would be like...", objectives = "Kill 10 Marshfang Rippers and return to Noraani at Telredor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9792] = { id = 9792, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Message to Telaar", description = "You've been honorable in our dealings, {name}, at a time when trust is hard to win among my people.\n\nA large group of my brethren have made their home in the old draenei city of Telaar in Nagrand, to the south. To reach Telaar, take the road south into Nagrand, then continue southeast until you find yourself in the cliffs east of Oshu'gun.\n\nAnyone who has aided us, as you have, would be welcome among the people of Telaar.\n\nSeek out Warden Moi'bff Jill and tell him you have earned my trust.", completion = "Ikuti is like a brother to me. A friend of his is a friend of mine. You are welcome here, {name}, and you have our thanks for assisting our people.", objectives = "Speak with Warden Moi'bff Jill at Telaar in Nagrand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9793] = { id = 9793, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fate of Tuurem", description = "Prophet Velen's search for allies has emboldened those draenei remaining in Outland to begin a search of their own. The Legion's war on my people drove us from our cities and temples, but they have not destroyed the traces of our civilization.\n\nTuurem, my former home in the Terokkar Forest, was one of the first cities overrun by the orcs. It's been too long since I've received news of its status. Take this letter to Andarl in the Allerian Stronghold within Terokkar and see what you can find out.", progress = "How may I help you?", completion = "Hmm... I remember hearing our scouts speak of the ruins of a draenei settlement in the forest's northern reaches. I don't know much about the ruins, personally, but you're welcome to talk to some of the scouts.", objectives = "Take Vindicator Idaar's Letter to Andarl at the Allerian Stronghold in Terokkar Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9794] = { id = 9794, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Time for Curiosity", description = "{name}, I have a favor to ask of you. Normally, I would do this myself, but my hands are already beyond full.\n\nI have an associate named Kialon at Sylvanaar in the Blade's Edge Mountains to the north. He's expecting to hear from me in the near future, although I suspect he won't like what I have to say.\n\nIf you would deliver my response to him, you would have my gratitude. I must insist, and this is very important, that you not attempt to read the letter. It is for Kialon's eyes alone.", progress = "<Kialon eyes you suspiciously.>\n\nI don't know you, {race}. Do you have business with me?", completion = "So you've brought Timothy's response?\n\n<Kialon pauses a moment to read the letter, then laughs.>\n\nHe's got everything under control, he says. Doesn't need help, he says. I could've predicted that!\n\nSome people never change. Look, he even took the time to correct my spelling.\n\n<Kialon lets out a half-hearted sigh.>\n\nI shouldn't have sent the letter. I forgot. The specialist always has the situation under control. Always.", objectives = "Deliver Timothy's Letter to Kialon at Sylvanaar in the Blade's Edge Mountains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9795] = { id = 9795, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ogre Threat", description = "As if the naga and their allies weren't enough, the ogres are extending their reach in the marsh. They've already conquered most of the area to the northwest and there isn't much of a buffer left.\n\nFor each one we kill, several more take their place. I'm not sure how long we'll be able to hold Zabra'jin once they decide to attack. Make your way north into the mountains, to the orcish stronghold of Thunderlord Stronghold and let Nekthar know of our plight. Any help he can spare would be most welcome.", completion = "Denjai seeks help?  I'd send him reinforcements, but we're spread thin here as it is.  We've got trouble of our own with the ogres up here.\n\nWhen I can, I'll give him what information we have on the local ogre tribes and their tactics.  Perhaps if he can survive long enough, we'll be able to launch a two-pronged assault on the vile scum.", objectives = "Travel to Thunderlord Stronghold in the Blade's Edge Mountains and speak with Nekthar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9796] = { id = 9796, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "News from Zangarmarsh", description = "Shadow Hunter Denjai isn't the only one expecting a report from me. Mokasa at Stonebreaker Hold in Terokkar is eager to hear of our progress, especially since most of her messengers travel through here.\n\nShe asked me to send word once Swamprat Post was completed. If you wouldn't mind delivering the news, I'd be very grateful. We may be up and running, but there is still much to be done.\n\nTo get to Stonebreaker Hold, follow the road south out of Zangarmarsh, into Terokkar Forest and beyond Tuurem.", completion = "It's about time he got that outpost up and running. We've lost far too many runners to Alliance outriders.", objectives = "Speak with Mokasa at Stonebreaker Hold in Terokkar Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9797] = { id = 9797, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reinforcements for Garadar", description = "<Still catching his breath, the messenger gestures for you to sit.>\n\nThey may not survive, {race}! Get to Garadar as quickly as your legs will carry you.\n\n<In response to your blank stare, the messenger elaborates.>\n\nThe home of the Mag'har, lies to the south, in Nagrand. Take the southern road out of the marsh, then turn east at the first fork and look for a large settlement on the lake.\n\nFind our commander, Captain Kroghan, there and offer him what assistance you can. Garadar must not fall!", completion = "<Even though he endeavors to hide it, a look of relief spreads over Kroghan's face.>\n\nIt's about time you got here! Granted, you're not an army, but any able-bodied {race} than can wield a weapon or chant a spell is welcome here. The people of Garadar are kin to all the Horde and we are proud to shed our blood in their defense.", objectives = "Speak with Captain Kroghan at Garadar in Nagrand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9798] = { id = 9798, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood Elf Plans", description = "These plans seem important.  You should take them to Vindicator Aldar at the crash site.", progress = "What have you got there?", completion = "Here, let me read those plans.\n\nThe blood elves have followed us here?  They are evil to the core and should be wiped from existence!\n\n<The vindicator takes a moment to regain his composure.>\n\nI apologize, that was uncalled for.  We are indebted to you for uncovering this information, {name}.", objectives = "Take the Blood Elf Plans to Vindicator Aldar at the Crash Site in Ammen Vale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9799] = { id = 9799, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Botanical Legwork", description = "The Ammen Fields to the west are the primary breeding ground of the local lasher population. With the corruption of the water table from the nearby lake, Botanist Taerix is worried that the lashers will not be able to repopulate themselves once we've cleansed the lake.\n\nGo to the Ammen Fields and pick some of the corrupted flowers for me so that I might take a look at them and see what can be done. You should be able to identify them by their uncharacteristic red petals.", progress = "Hello, {class}.  Do you have those flowers yet?", completion = "These look like fine specimens.  Thank you for performing the field work.  Once I can find the time to analyze these, I should be able to tell what it will take to restore the fields.", objectives = "Gather 3 Corrupted Flowers and return them to Apprentice Vishael at the Crash Site in Ammen Vale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9800] = { id = 9800, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Rare Bean", description = "You are ill-equipped to face the restless elements of Nagrand. Before you can help the Earthen Ring, you must help yourself.\n\nTo the west you will find dung heaps left behind by the wildlife of Nagrand. You must search the dung for the digested remnants of the Nagrand caracoli. From this bean I am able to make a tablet that will aid you in your battle against the restless forces of nature.\n\nReturn to me when you have collected no less than two fists worth of caracoli... Ogre sized fists.", progress = "<Elementalist Lo'ap makes two fists and shakes his head in disapproval.>\n\nOgre sized...", completion = "Please do not wash yourself in the sacred waters of the Throne.\n\n<Elementalist Lo'ap holds a prepared caracoli tablet up.>\n\nYou place this under your tongue and allow it ample time to dissolve. Once it has dissolved, you will be able to breathe water as if it were air.", objectives = "Elementalist Lo'ap at the Throne of the Elements in Nagrand wants you to bring him 8 Digested Caracoli.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9801] = { id = 9801, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gathering the Reagents", description = "I have a feeling that these Lost Ones may not respond well to a draenei, but would welcome an arakkoa. I can create a potion that will allow you to take on the form of an arakkoa for a short time. It requires a couple of reagents which cannot be stored and must be used within hours of being gathered.\n\nYou will need to bring me a handful of sporebat eyes and some fen strider tentacles. Both species dwell in the wilderness surrounding Telredor.", progress = "Have you gathered the reagents?", completion = "These will do quite nicely. Allow me a moment to mix up the potion.", objectives = "Anchorite Ahuurn at Telredor wants you to bring him 4 Sporebat Eyes and 4 Fen Strider Tentacles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9802] = { id = 9802, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plants of Zangarmarsh", description = "The lakes of Zangarmarsh are slowly being drained of their water.  We don't quite know why, but we do know that many plants species are in danger of becoming extinct.\n\nAs the expedition's cataloguer, it is my job to track and identify these plants so we can better understand what's happening to them.\n\nIf you'd like to help, bring me unidentified plant parts.  They can be picked right from the ground if you're an herbalist, and the indigenous creatures of the swamp may also carry plant parts on them.", progress = "Did you find any plant parts, {name}?", completion = "The decrease in native species is certainly a cause for concern.  The increase in invasive species could be related to the recent disturbance in the ecosystem.  I don't have enough information to make a conclusion, yet.\n\n<Lauranna jots down some notes on a journal as she goes through the plant parts.>\n\nTake these, {name}.  They might be of some use to you.\n\nBring me any other plant parts you find.  I'll incorporate them into my statistics.", objectives = "Bring 10 Unidentified Plant Parts to Lauranna Thar'well at the Cenarion Refuge in Zangarmarsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9803] = { id = 9803, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Messenger to the Feralfen", description = "The time has come for us to embrace the Feralfen and teach them that the Light has not forsaken them. Take the potion I've prepared and carry it with you to the Boha'mu Ruins.\n\nOnce you arrive at the ruins, drink the potion to assume the form of one of their bird spirits. Speak with Elder Kuruti and let him know the draenei are ready to welcome his people as our long lost brothers.", progress = "Did you speak with the Feralfen elder?", completion = "They refused? They are welcome to choose their own path, of course, but their choice surprises me. I would think that all the draenei, including the Broken and Lost Ones, would still remember that we're all a part of the same people.\n\nI suppose he is right about the folly of deceiving them, but still, could he not see that our intentions were friendly?", objectives = "Drink Ahuurn's Elixir while standing in the Boha'mu Ruins. Speak to Elder Kuruti while you are in the form of an arakkoa.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9804] = { id = 9804, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agitated Spirits of Skysong", description = "The disturbance in the ebb and flow of the waters of Nagrand has greatly agitated the water spirits of Skysong Lake. They have in turn begun sowing destruction throughout the waterways of the area.\n\nWatoosun of the Water has come to us in a vision and granted us permission to remedy the problem - so long as the source of the disturbance is also dealt with...\n\nWe will get to the source, but first you must deal with the problems immediate to the Throne. Destroy the agitated lake spirits and return to me.", completion = "<Elementalist Lo'ap kneels in the water and says a prayer.>\n\nThe Earthen Ring takes no pride in what was done. We do what we must to heal the land.", objectives = "Elementalist Lo'ap at the Throne of the Elements in Nagrand wants you to destroy 8 Lake Spirits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9805] = { id = 9805, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blessing of Incineratus", description = "The wretched Lost Ones, heretofore banished to the swamps of Zangarmarsh, are seeking to spread their filth to other parts of our world.\n\nI have sought the wisdom of the furies and gained their blessing. To stop the source, we must unleash the elements upon them!\n\nI give you living fire, plucked from the fiery essence of Incineratus himself. Travel to Windyreed Village, southeast of here, and unleash the living fire upon their huts! Let them see the fury of the elements!", completion = "Your efforts have stifled the spread of pollution but other troubles have surfaced.", objectives = "Elementalist Lo'ap at the Throne of the Elements in Nagrand wants you to destroy the Large Hut, the Western Hut, the Southern Hut and the Eastern Hut at Windyreed Village.\n\nReturn the Living Fire to Elementalist Lo'ap when the task is complete.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9806] = { id = 9806, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fertile Spores", description = "Spore bats and marsh walkers accumulate fertile spores on their appendages from wandering around the tallstalk mushrooms in the marsh.\n\nAs you can see, we're a short people so our options for gathering these spores are limited.  Seek out the spore bats and marsh walkers and gather the fertile spores.  All of Sporeggar will be in your debt.", progress = "You're back, {name}.  Did you obtain the fertile spores?", completion = "These are great spores, {name}!  Tallstalks are vital to rebuilding our town.  And after all the bog lord attacks we've suffered, we're in quite the short supply.", objectives = "Gshaff wants you to gather 6 Fertile Spores from the various Zangarmarsh Spore Bats and Marsh Walkers. Return to Gshaff at Sporeggar when you've completed this task.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9807] = { id = 9807, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Fertile Spores", progress = "We can always use more fertile spores, {race}.  Tallstalks are incredibly useful mushrooms.  Being able to grow them lets us do many things with them.", completion = "Your help is appreciated, {name}.  You will keep it up, yes?" }
quests[9808] = { id = 9808, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glowcap Mushrooms", description = "I've seen your kind use shiny round pieces of metal to trade for things that you need.  We're not so different from you.  We use shiny round mushrooms as our currency.\n\nGlowcap mushrooms grow everywhere in the marsh, you just have to know how to pick them from the ground without wrecking them.  I'll teach you how to do it, if you promise to bring us some for our reserves.  What do you say, {name}?", progress = "Did you find any glowcaps, {name}?  They're literally everywhere in the marsh.\n\nYou can spot their bright glow from far away if you pay attention.", completion = "This will help us trade with other sporelings for food and supplies.  Sporeggar thanks you, {name}!", objectives = "Bring 10 Glowcaps to Msshi'fn at Sporeggar in Zangarmarsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9809] = { id = 9809, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Glowcaps", progress = "I'll take more glowcaps if you have them.  Our village can always use more of them.", completion = "Thank you, {name}.  As Sporeggar's elder, I must ensure my people have adequate supplies.  You make my task that much easier." }
quests[9810] = { id = 9810, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Spirit Polluted", description = "Watoosun was able to shed the stink of corruption; but in doing so, created a twisted spirit essence. A spirit essence composed of the vilest corruption found amongst the elements!\n\nYou will find this polluted spirit of the swamp southwest of here, hidden in the depths of Lake Sunspring.\n\nFind and destroy the polluted essence of Watoosun and any corrupt offspring that it may have created.", completion = "The elements sang of your victory the moment the disturbed essence was destroyed! The Earthen Ring thanks you and wishes for you to choose a reward.", objectives = "Elementalist Lo'ap at the Throne of the Elements in Nagrand wants you to destroy Watoosun's Polluted Essence and 8 Lake Surgers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9811] = { id = 9811, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Friend of the Sin'dorei", description = "This is the beginning of a new chapter in blood elf history, {name}.  You've helped cement the bond between my race and yours, {race}.\n\nTake the traitor's head to Regent Lord Lor'themar Theron in Silvermoon City.  He'll be eager to hear the news.", progress = "You seek audience with me, {class}?  I do not recall hearing of an appointment.", completion = "So you killed Dar'Khan, {race}?  Impressive.  I've a feeling my people and yours will soon get to be very good friends.", objectives = "Take Dar'Khan's Head to Lor'themar Theron in Silvermoon City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9812] = { id = 9812, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Envoy to the Horde", description = "There were doubts about our capabilities among our potential new allies.  Of what use could we be to them when perceived as unable to deal with our problems at home?\n\nThis changes everything.  No longer will our power be questioned.  We'll be able to join the Horde as equals.\n\nTake this letter to Sylvanas, ruler of the Forsaken.  She's already on our side but the news of Dar'Khan's death will be music to her ears.  Prepare for a long trip, {name}.  If all goes well she will send you to Orgrimmar.", progress = "I was told a visitor from Quel'Thalas was coming. I was expecting a blood elf, to tell you the truth.\n\nWhat news do you bring?", completion = "It is done then. The foul traitor got what he deserved.\n\nYou've been of great service to the blood elves and to the Horde. Dar'khan was Thrall's excuse to deny them entry into our alliance. You've cleared the way for a new Horde, {class}.\n\nI also see that Lor'themar has additional news that will greatly improve his relations with Thrall. Excellent!", objectives = "Bring the Letter from Lor'themar Theron to Lady Sylvanas Windrunner in Undercity, the Forsaken capital in Tirisfal Glades.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9813] = { id = 9813, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meeting the Orcs", description = "I haven't lost any love for my homeland or its people, as you know. I've fought tooth and nail for Silvermoon to be allowed a place beside Undercity and Orgrimmar at the negotiating table.\n\nThis should silence any opposition. Take this letter to Saurfang in Orgrimmar. As leader of the orcs, he must have a say in accepting the sin'dorei's pledge.\n\nI've added my own seal to the letter as a personal endorsement. Go northwest of the city and board the zeppelin bound for Durotar at the tower.", progress = "Yes, {class}?", completion = "<The Warchief begins to read the letter.>\n\nSo the blood elves finally took care of their little problem.  It is no surprise that it took your help as well as that of an entire Forsaken regiment to get the job done.\n\n<The Warchief breaks into laughter.>\n\nI suppose there's no stopping this.  In the end we need them just as much as they need us.", objectives = "Lady Sylvanas Windrunner wants you to take the Letter Sealed by Sylvanas to High Overlord Saurfang in Orgrimmar, capital of Durotar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9814] = { id = 9814, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burstcap Mushrooms, Mon!", description = "You like mushrooms, mon? There be a powerful one here in Zangarmarsh, growin' real close to Zabra'jin.\n\nYou gotta be careful, though, mon. They be callin' it the burstcap for a reason. If you be gettin' too close without takin' the proper precautions, it'll blow right up on you! Poof! Right into a cloud o' toxic spores.\n\nI been usin' them for readin' the omens, but they be almost gone now.", progress = "Have you got the mushrooms, mon?", completion = "These be excellent, mon!\n\nI'll tell you what. Since you been a good sport and helped with the mushrooms, I'll let you in on the fun!", objectives = "Bring Witch Doctor Tor'gash 6 Burstcap Mushrooms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9815] = { id = 9815, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muck Diving", description = "The most affected elements of water can be found in the Halaani Basin, southwest of here, beneath the abandoned city of Halaa. While some distressed elements can be destroyed without any impact upon the environment, spawns of muck must be physically removed from the world once destroyed.\n\nYou see, muck spawns leave behind globules of tainted debris that if left untouched will spread and further contaminate the environment.\n\nDestroy these muck spawns and bring back their muck-ridden cores.", progress = "Do not leave any tainted muck behind!", completion = "The Earthen Ring thanks you, {name}. The elements also give their thanks. Your continued efforts in cleansing our world are appreciated and noted.", objectives = "Elementalist Lo'ap at the Throne of the Elements in Nagrand wants you to retrieve 5 Muck-ridden Cores.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9816] = { id = 9816, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Have You Ever Seen One of These?", description = "This marsh be missin' one thing, mon! There be no murlocs here.\n\nDon't worry, mon, I got a plan to fix the problem. See Gargle 'n' Gurgle over there? I plan to give the gift o' murlocs to the Lost Ones!\n\nTake this cage with you to Daggerfen Village an' release 'em in the northeastern cluster of huts. Now you know I can't be riskin' Gargle 'n' Gurgle with you, but I'll give you a cage full o' colorful young murlocs. Just set it on the flat rock you be findin' up there and open the door!", completion = "Excellent work, mon! I do hope they had a good time!", objectives = "Take the Murloc Cage and place it on the flat rock near Daggerfen Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9817] = { id = 9817, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leader of the Bloodscale", description = "A bounty is hereby declared by the Cenarion Expedition on Rajis Fyashe, leader of the Bloodscale naga.  The naga sorceress was last sighted at Serpent Lake, in the northern region of Zangarmarsh.\n\nThe Bloodscale are to be considered extremely dangerous and their leader is to be approached with extreme caution.\n\nThose seeking to claim the bounty are advised to report to Warden Hamoot at Cenarion Refuge.", completion = "I'll bet the Bloodscale will think twice about attacking expedition scouts again.  Take this as a reward, {name}.  You've earned it.", objectives = "Slay Rajis Fyashe at Serpent Lake and return to Warden Hamoot at the Cenarion Refuge in Zangarmarsh for a reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9818] = { id = 9818, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Underneath", description = "Something rails the underneath. It beats the ground as if to punish.\n\n*Thud*\n\n<Untrag beats his chest with his fist.>\n\nIt makes this sound a hundred-thousand times. Endlessly it beats. The earth reels. It is calling out to us now.\n\nGordawg speaks to me. Gordawg knows that something forces the elements out. Something from the underneath.\n\nGo now and speak to Gordawg. No, listen to Gordawg, do not speak. Hear Gordawg...", completion = "<Gordawg appears to be nodding at you.>\n\nSit.", objectives = "Communicate with Gordawg.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9819] = { id = 9819, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tortured Earth", description = "Bring up the usurper. You will find him. Follow earthen path. First you put to rest tortured earth spirits. Must sleep once more.\n\n<Gordawg smashes his fist into the ground and brings up very foul smelling soil.>\n\nMust sleep!\n\n<Gordawg points southeast.>\n\nFind spirits near mountains. Near hills. Near rocks. Near earth.\n\nPut to sleep.\n\nTelaari Basin... Southeast.", progress = "Do they sleep?", completion = "<Gordawg nods in approval.>\n\nGood. Spirits sleep now.", objectives = "Gordawg at the Throne of the Elements in Nagrand has asked that you destroy 10 Tortured Earth Spirits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9820] = { id = 9820, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Boss Grog'ak", description = "Wanted - Dead or Alive: Boss Grog'ak, overseer of the Ango'rosh mushroom-cutting operation.\n\nThis brute and his axe-wielding cronies are responsible for chopping down the mushrooms to the north of town. Unless he is stopped, he and his band will cut a path to the walls of Zabra'jin.\n\n<He/She> who presents the head of Boss Grog'ak to Shadow Hunter Denjai shall be well-rewarded.", progress = "What do you have there, {name}?", completion = "Well done, {name}. The presence of these ogres so close to our outpost does have me worried, though. It seems like they've been filtering down from the northern mountains for some time.", objectives = "Bring Boss Grog'ak's Head to Shadow Hunter Denjai in Zabra'jin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9821] = { id = 9821, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eating Damnation", description = "<Gordawg picks up a rock and begins to chew on it.>\n\nGordawg tastes. Gordawg knows where this earth has been.\n\n<Gordawg raises one of his massive legs and stomps the ground.>\n\nLook. See Nagrand.\n\n<Gordawg directs you to the imprint of his foot. Within the imprint you see what appears to be a perfect geological map of Nagrand, marked with the locations of where you can find the elementals Gordawg wants you to destroy.>\n\nBREAK THEM! Bring Gordawg the pieces to eat.\n\nTake the map.", progress = "Gordawg eats this rock. Gordawg finds usurper. Bring rock!", completion = "<Gordawg spits out the chewed up rock, pelting you with a hail of rubble.>\n\nPoison. These rocks are not Nagrand. These rocks are from poison. You destroy poison rock. You find usurper.", objectives = "Gordawg at the Throne of the Elements in Nagrand has asked that you bring him 10 Enraged Crusher Cores.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9822] = { id = 9822, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Impending Attack", description = "The position of the ogres' mushroom-cutting operation can't be an accident. I can't escape the suspicion that they're preparing for an attack on Zabra'jin.\n\nI must know for certain, {name}. The ogres have another outpost to the northwest, the Ango'rosh Grounds. If they're staging for an attack, there will be evidence of their plans there. Go there, {name} and search the camp for signs of their intentions. Return to me with anything that might be suspicious.", progress = "Have you found proof of the ogres' intentions?", completion = "<Shadow Hunter Denjai examines the plans.>\n\nI knew it! The stench of ogres always carries an implicit threat. Now that we have proof of their intentions, we must act before they do.", objectives = "Bring the Ango'rosh Attack Plans to Shadow Hunter Denjai in Zabra'jin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9823] = { id = 9823, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Us or Them", description = "In order to end the Ango'rosh threat, we must kill their leader, Overlord Gorefist. We'll do better than that, though. We'll make an example of the overlord and his followers.\n\nGo to the Ango'rosh Stronghold and deal with our foes. The stronghold is located in a cave on a small island to the northwest of Zabra'jin. You'll see a bridge made from a fallen mushroom beyond the Ango'rosh Camp.\n\nShow no mercy, {name}. They certainly wouldn't spare any of us.", completion = "Your victory over the Ango'rosh is to be celebrated, {name}. I wonder how long it will be before those ogre brutes find themselves another bloodthirsty chieftain.\n\nNo matter, we'll be ready for them.", objectives = "Kill Overlord Gorefist, 10 Ango'rosh Maulers, and 10 Ango'rosh Souleaters and report back to Shadow Hunter Denjai in Zabra'jin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9824] = { id = 9824, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcane Disturbances", description = "I'm trying to obtain an imprint of Karazhan's energy... for a personal project, of course.  Unfortunately, I'm not getting anything up here.  If I could get near an underground water source, my crystal would pick up the signals much more clearly.\n\nI've heard of an underground pond as well as a well in a cellar below us.  This whole place is crawling with ghosts however, and venturing there would be hazardous for someone my age.  What do you say; will you help an old man and perform the scrying for me?", progress = "The readings, {name}.  Did you complete them?", completion = "These readings do not bode well, {name}.  Karazhan should be emanating all manner of arcane currents... instead it has become a huge energy vacuum.  No signals.  Nothing.  Except for a very faint demonic echo.\n\nThis is bad news, {name}.", objectives = "Use the Violet Scrying Crystal near underground sources of water in the Master's Cellar and return to Archmage Alturus outside of Karazhan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9825] = { id = 9825, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restless Activity", description = "As you may have noticed, the outside of Karazhan is crawling with ghostly beings. The reason for their existence is unknown and unknowns bother me!\n\nBring me their ghostly essence so that I may study their nature.  Karazhan has many secrets, {name}.  I'm determined to uncover all of them.", progress = "Have you obtained the ghostly essences I require, {class}?", completion = "Fascinating.  I will study these essences, {name}.  I thank you for your help.", objectives = "Bring 10 Ghostly Essences to Archmage Alturus outside of Karazhan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9826] = { id = 9826, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Contact from Dalaran", description = "These signs do not bode well for us, {name}.  I've never been one for secrecy so I will tell you a bit about my organization, the Violet Eye.\n\nWe are agents of the Kirin Tor, the Magus Senate of Dalaran.  We were assigned to keep an eye on Karazhan and Medivh, in case things got out of hand.\n\nWhich they did... very quickly, after Medivh disappeared.\n\nThis report details my findings.  Take it to Archmage Cedric, also from the Violet Eye; you will find him in the outskirts of Dalaran Crater.", progress = "You know of the Violet Eye?  You do not look familiar.", completion = "Alturus entrusted you with this information?  That old fool.\n\nI suppose the damage is done, we might as well make use of you.  I suppose you will cooperate?", objectives = "Bring Alturus's Report to Archmage Cedric in the outskirts of Dalaran Crater.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9827] = { id = 9827, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Withered Basidium", description = "A close inspection of the basidium reveals a number of indentations that might have once held something. The alien mass of fungus presents something of a puzzle. It's far from healthy, but you have little clue as to what function it might normally perform.\n\nPerhaps someone more familiar with the denizens of Zangarmarsh would be able to tell you more about the basidium.", progress = "What is it you have there, {name}?", completion = "It looks like the basidium of a bog giant, but I haven't seen one in this condition before. I'd heard that the giants in the Dead Mire had begun to wither, but it's far more advanced than I expected.\n\nThe Dead Mire was once a lake like the others in the marsh, and it served as the spawning ground for the giants. With the waters receding, it seems the changes are preventing the giants from sporing. If this continues, the giants may disappear entirely.", objectives = "Take the Withered Basidium to Ruam in Telredor in Zangarmarsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9828] = { id = 9828, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Withered Basidium", description = "A close inspection of the basidium reveals a number of indentations that might have once held something. The alien mass of fungus presents something of a puzzle. It's far from healthy, but you have little clue as to what function it might normally perform.\n\nPerhaps someone more familiar with the denizens of Zangarmarsh would be able to tell you more about the basidium.", progress = "What is it you have there, {name}?", completion = "It looks like the basidium of a boglord, but I haven't seen one in this condition before. I'd heard that the giants in the Dead Mire had begun to wither, but it's far more advanced than I expected.\n\nThe Dead Mire was once a lake like the others in the marsh, and it served as the spawning ground for the giants. With the waters receding, it seems the changes are preventing the giants from sporing. If this continues, the giants may disappear entirely.", objectives = "Bring the Withered Basidium to Reavij at Swamprat Post in Zangarmarsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9829] = { id = 9829, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Khadgar", description = "Alturus's report is unsettling.  We thought it was bad when Karazhan sealed itself off to the outside world.  We had agents inside; we never heard from any of them again.  Now this... demonic emanation.  We must investigate it.\n\nThe only people who can reopen Karazhan were presumed dead: Khadgar and Medivh.\n\nWhile we hope that the latter is indeed gone, we recently learned that his apprentice, Khadgar, is alive and well in a place called Shattrath City.  Find him and give him Alturus's report.", completion = "The Violet Eye?  You don't say.\n\nShow me this report you speak of.", objectives = "Deliver Alturus's Report to Khadgar in Shattrath City in Terokkar Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9830] = { id = 9830, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stinger Venom", description = "When I speak to draenei, I often get the sense that they consider themselves removed from their environment. Many seem to pity my brethren, the Broken, who they say have lost something.\n\nWe Broken may have lost our inclination toward the Light, but our experiences have brought us closer to the land.\n\nMy people see opportunities where few draenei do. Take, for example, the venom of the marshlight bleeders that live to the south and west. It has a wide variety of uses from hunting to healing.", progress = "I hope to demonstrate the uses of bleeder venom to Anchorite Ahuurn and the others at Telredor. That's going to require me to double my supply.", completion = "Thank you for bringing this venom, {name}. It will go a long way toward making my demonstration possible without depleting my personal stores.", objectives = "Bring 6 Marshlight Bleeder Venom to Puluu at the Orebor Harborage.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9831] = { id = 9831, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entry Into Karazhan", description = "I am deeply troubled by the news in this report, {name}.  Gaining entry into Karazhan will be difficult, however.\n\nYou see, when it became apparent that I was stranded here I split the key into three fragments.\n\nI placed the keys inside enchanted containers, and in turn placed those in places that were safe at the time.\n\nWith the dark changes Outland has endured this no longer is the case.  The first fragment is in a section of Auchindoun taken over by the Shadow Council.  Return this fragment to me.", progress = "Have you obtained the fragment, {class}?  You would do well not to waste any time in this matter.", completion = "You've done well, {name}.  I wasn't sure you would succeed.\n\nThe containers are enchanted with a potent spell that masks their presence from unworthy eyes.  I'm glad to see they did not elude you.", objectives = "Khadgar wants you to enter the Shadow Labyrinth at Auchindoun and retrieve the First Key Fragment from an Arcane Container hidden there.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9832] = { id = 9832, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Second and Third Fragments", description = "I hid the second fragment at the bottom of Serpent Lake, long before it was called that.  The giant drain installed there after the naga took over has likely pulled the container into the depths of Coilfang Reservoir.\n\nThe third fragment will prove the most trying, as I left it inside Tempest Keep back when it was controlled by the naaru.  Kael'thas now rules it and the chamber where I left it has become a prison.\n\nBring me these remaining fragments, {name}.  Much depends on your success.", progress = "How goes your search for the key fragments, {name}?", completion = "You have the fragments.  This is most impressive, {name}.  You're certainly worthy of holding the key to Karazhan.\n\nA small problem remains.", objectives = "Obtain the Second Key Fragment from an Arcane Container inside Coilfang Reservoir and the Third Key Fragment from an Arcane Container inside Tempest Keep. Return to Khadgar in Shattrath City after you've completed this task.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9833] = { id = 9833, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lines of Communication", description = "One of the reasons Ikuti led us to Zangarmarsh was to help open the lines of communication between the draenei and the Kurenai home city of Telaar in Nagrand. In order for messengers to pass swiftly between Telaar and Telredor, the roads must be secured.\n\nOn our way here, we were attacked repeatedly by marshfang slicers. We were able to fight them off, but they would pose a formidable threat to a solitary messenger. Reducing their numbers will help ensure the safety of our messengers.", completion = "That's excellent news. The way is still far from perfectly safe, but the messengers are clever and resourceful.", objectives = "Puluu at the Orebor Harborage wants you to kill 12 Marshfang Slicers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9834] = { id = 9834, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Natural Armor", description = "Maktu can always see a draenei approaching in his shiny armor from a mile away, even in this murky swamp!\n\nMaktu wants to laugh at them, but then he remembers that they have been kind to the Kurenai and he wants to teach them about how Kurenai make armor.\n\nThe dark, scaly hides of the fenclaw thrashers make some of the best armor Maktu has ever worn. If {name} can bring Maktu some of these hides from the fenclaw thrashers deep in Serpent Lake, he'll be happy to share some of his armor.", progress = "Does {name} have hides for Maktu?", completion = "These are good hides, Maktu thinks. They will make very good armor.\n\nWho knows? There might even be enough left over for Maktu to make some armor for the draenei.", objectives = "Bring 8 Fenclaw Hides to Maktu at the Orebor Harborage.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9835] = { id = 9835, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ango'rosh Encroachment", description = "The small band of Broken you see here is a mission from a larger settlement in Nagrand. The Kurenai, as we call ourselves, are Broken who desire to reunite with our draenei brothers.\n\nMy group has come here to strengthen Kurenai ties to the draenei of Telredor.\n\nIf the Ango'rosh ogres have their way, this temple will not stand much longer. They have cleared the Hewn Bog of its towering mushrooms and draw ever closer to our refuge. If you would call yourself our friend, aid us in fighting this enemy.", completion = "The Ango'rosh threat is contained for the moment, but I'm certain they won't give up that easily. I've forgotten many things since the end of my life as a draenei, but the stubbornness of the ogres is an enduring memory.", objectives = "Kill 10 Ango'rosh Ogres and 5 Ango'rosh Shaman and return to Ikuti at the Orebor Harborage.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9836] = { id = 9836, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Master's Touch", description = "I've put together the very key I used as an apprentice.  It looks completely functional as far as keys go.  In regards to opening Karazhan, however, this might as well be a piece of scrap metal.\n\nWithout Medivh's consent, the key is worthless.  Yes, of course I know Medivh is dead.  This merely makes things difficult, not impossible.\n\nThere is a place in Azeroth called the Caverns of Time, guarded by the bronze dragonflight.  Find a way inside, travel back in time and get Medivh to enable the key.", progress = "Who are you and what do you want?", completion = "That key, I recognize it.  That is Khadgar's key... of course I haven't given it to him yet.", objectives = "Go into the Caverns of Time and convince Medivh to enable your Restored Apprentice's Key.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9837] = { id = 9837, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Khadgar", description = "I seem to have memories about future events surrounding you and this key.\n\n<Medivh looks at you like he's just seen a ghost.>\n\nYou have trying times ahead of you, {name}.  Let us hope your strength does not fail you.\n\nRegarding the key, I am to hand it to Khadgar when he's sent to me.  I couldn't hope for a better apprentice.\n\nI suppose you will need a key of your own.\n\n<Medivh reaches into his robe and hands you his own key.>\n\nGo on then.  And best of luck, {class}.", completion = "His own key?  That's incredible!\n\nI do not sense any disturbances in our timeline, so I suppose it was meant to occur all along.  There's no turning back now, {name}.  The key is yours and only yours.", objectives = "Return to Khadgar in Shattrath City and show him the Master's Key.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9838] = { id = 9838, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Violet Eye", completion = "I sent you to deliver a report and you come back with a key to this place?  There must be more to you than meets the eye, {name}.", objectives = "Speak to Archmage Alturus outside Karazhan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9839] = { id = 9839, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Overlord Gorefist", description = "The centerpiece of any ogre tribe is its leader. Without leadership, the Ango'rosh's organization will disappear and they'll resort to infighting to determine who will lead next.\n\nAlthough we've seen the ogres out and about in this area, their true strength is concentrated in their Ango'rosh Stronghold to the northwest. It's located in a cave on a small island connected to the marsh by a fallen mushroom.\n\nGo there and defeat Overlord Gorefist. That should provide us with a well-deserved respite.", progress = "Is it done? Have you dealt with Overlord Gorefist?", completion = "At last! You have our thanks for your help in securing our position at the Orebor Harborage. I will send word of your deeds to the Kurenai city of Telaar in Nagrand. There will be many more opportunities for our peoples to work together.", objectives = "Ikuti wants you to kill Overlord Gorefist and 10 Ango'rosh Maulers. Return to the Orebor Harborage once you have completed the task.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9840] = { id = 9840, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assessing the Situation", description = "Now that we've found a way back into Medivh's Tower - or rather you have - the first thing we need to do is try to get a sense of what the situation inside is.\n\nOne of our agents who had managed to infiltrate Karazhan kept an encoded log of her observations.  Unfortunately her death was confirmed shortly before Karazhan was shut down.  Koren, Karazhan's blacksmith, was under our pay.  Though not a member of the Violet Eye, he should be able to help us find Keanna's log.  Look for him inside.", completion = "<Koren looks at you with an uncertain look.>\n\nI know nothing of this Violet Eye you speak of.  A blacksmith is all I am.", objectives = "Find Koren inside Karazhan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9841] = { id = 9841, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stinging the Stingers", description = "It's impossible to work with all this infernal buzzing! Do you hear it?\n\nI can't get it out of my head! I know exactly what's making the noise, too. It's those damnable marshlight bleeders! The noise always comes from the south and west of the village.\n\nThey're too big to swat, crush underfoot, or wave away. The only way to stop that unholy droning is to kill them. I don't care how you do it, {name}, just quiet them!", completion = "I thought so. I can hear the difference already. I'll finally be able to get back to work, thanks to you. If you ever find yourself in need of tradeskill supplies, don't forget ol' Gambarinka!", objectives = "Kill 8 Marshlight Bleeders and return to Gambarinka at Zabra'jin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9842] = { id = 9842, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sharpest Blades", description = "The damp atmosphere of the marsh has taken a toll on my metal tools. It's made woodworking a lot more difficult than it ought to be, so I've given up on metal blades.\n\nIt turns out that the marshfang slicers living to the south and west of town grow blades that are sharper than any steel I've ever owned. They're also resistant to rust and wear. It's just a little tricky to attach them to a handle, but I think I've got it figured out. I'd appreciate any blades you could bring me.", progress = "Have you managed to scare up some of those marshfang blades?", completion = "These should keep me supplied for some time to come! I think some of the others have begun to take notice. I've had several offers to buy my blades already. Selling them on the side might provide better business than my customary goods.", objectives = "Bring 10 Marshfang Slicer Blades to Gambarinka at Zabra'jin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9843] = { id = 9843, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keanna's Log", description = "Who did you say you were looking for again?  Keanna?\n\nI once met someone with that name.  She was staying up at the guest chambers.  I was supposed to keep that a secret now, wasn't I?\n\nDid you say you were with the Violet Eye?  No, I've never heard of them.\n\nI need to return to my work now, if you don't mind.\n\n<Koren seems to have forgotten about you already.>", progress = "Keanna's log... did you find it?", completion = "You found the log.  I sure hope the information we need is in here, {name}.", objectives = "Search the Guest Chambers inside Karazhan for Keanna's Log and bring it to Archmage Alturus outside Karazhan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9844] = { id = 9844, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Demonic Presence", description = "Keanna's last few entries confirm our suspicions of a demonic presence inside Karazhan.\n\nShe detected the arrival of a Burning Legion agent whose location she describes as coming from the top of the tower.\n\nHer entries stop there.\n\nKarazhan is a very important place, {class}.  It is a portal into the nether, a beacon shining into other worlds.  The possible repercussions of it falling into the wrong hands are unthinkable.  This demonic intrusion must be stopped.  And you, {name}, are the only one with a key.", completion = "You did it!  Yes, the readings are becoming normal once again!\n\nWe must give this news to Cedric.  He's going to be very impressed with your achievement.", objectives = "Archmage Alturus wants you to destroy the Demonic Presence at the top of Karazhan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9845] = { id = 9845, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angling to Beat the Competition", description = "It's a relief to be in someplace with water after trekking through the wasteland of Hellfire Peninsula. I was worried there might not be any respectable fishing holes in Outland.\n\nNow I'm glad I lugged my fishing supplies along. For the most part, the fishing's been good, except for those no good fenclaw thrashers in Serpent Lake.\n\nNot only do they scare the fish away, but they're bold enough to snap the bait right off my hook. I spend more time re-baiting the hook than I do catching anything!", completion = "I can't wait to return to fishing! Now I'll be able to return to town with some real fish in my bucket and Gambarinka won't be able to make fun of me anymore!", objectives = "Kill 10 Fenclaw Thrashers and return to Zurjaya at Zabra'jin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9846] = { id = 9846, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirits of the Feralfen", description = "The most powerful tribe of Lost Ones in the marsh, the Feralfen, are said to possess powerful medicine. There may be no truth to such rumors, but anything that might help me channel the spirits of this world cannot be ignored.\n\nFind the Feralfen mystics, hunters and druids, {name}, and capture their totems. Everything I need to know should be apparent from the carvings.", progress = "Have you gathered those totems?", completion = "Hmm... They seem to be divided between images of a serpent spirit and a bird spirit. No self-respecting Darkspear troll engages in bird worship. Their spirits are weak, capricious, and best left to the Amani.\n\nBut the serpent, {name}, the serpent wields considerable power and this is the spirit I shall study.", objectives = "Bring 10 Feralfen Protection Totems to Seer Janidi at Zabra'jin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9847] = { id = 9847, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Spirit Ally?", description = "We must find out how much power this Feralfen snake spirit possesses and whether it can be bent to our will. Imagine what I could do with the powers of an Outland spirit at my command!\n\nTake this totem with you and make your way to the foot of the stairs leading to the Boha'mu Ruins. Plant the totem in the ground and it should do the rest. The spirit should not be able to tell who has used the totem until it has manifested.", progress = "Were you able to summon the Feralfen spirit?", completion = "<You tell Seer Janidi about what happened when you used the totem.>\n\nThe spirit attacked you? It must have a higher affinity for those Lost Ones than I'd thought. There's no way to compel it to serve me without expending considerable effort. I'll have to search for a new source of power in this wretched world.", objectives = "Take the Feralfen Totem to the foot of the stairs at the Boha'mu Ruins and plant it in the ground. Report your findings to Seer Janidi at Zabra'jin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9848] = { id = 9848, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of the Daggerfen", description = "Bugs, bugs, bugs! The marsh is full of them and my companions here seem obsessed with them.\n\nWell, I've had it with the bugs! Something far more intriguing has captured my interest. To the west, there is a village of Lost Ones who call themselves the Daggerfen.\n\nThe whole tribe consists of highly specialized assassins. I've noticed them mixing and using a particularly potent kind of poison. I'm dying to know more about the poison, but that's going to require a copy of the recipe and a sample vial.", progress = "Did your search of Daggerfen Village yield the information I need in order to get to the bottom of this poison puzzle?", completion = "<Timothy leafs through the manual.>\n\nThey're using ragveil as a base for the poison? No, that can't be right. Ragveil has no toxic properties.\n\nIncluding ragveil in a poison is like a rogue wielding two maces. Sure, you can do it, but it isn't true to the essence of your calling! I just can't understand...\n\n<Timothy clears his throat.>\n\nI mean, thank you for fetching these for me. I'll try out the poison as soon as time permits.", objectives = "Bring the Daggerfen Poison Manual and a Daggerfen Poison Vial to Timothy Daniels at the Orebor Harborage.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9849] = { id = 9849, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shattering the Veil", description = "<Gordawg breaks off a piece of ebon rock from his back.>\n\nYou are granted a piece of the fury of the earth. Take the boulder of Gordawg and hurl it at the poison rock. Shatter their shells to discover the truth. Destroy the minions of the usurper and return to Gordawg with the name.\n\nYou find the shattered elements at the edge of the world. Southwest.", progress = "Gordawg wants the boulder returned.", completion = "GUROK! Gurok betrayed the elements!", objectives = "Gordawg at the Throne of the Elements in Nagrand has asked that you slay 30 Minions of Gurok.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9850] = { id = 9850, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clefthoof Mastery", description = "You've proved to me that you can find and take down a regular clefthoof, but far more dangerous are the clefthoof bulls.\n\nBag yourself twelve of those.  Then you can talk to me of your hunting prowess.\n\nLook for them all along the middle region of Nagrand to the west and south.", completion = "Impressive.  Most impressive.\n\nYou've got potential, kid.  Now I'm going to give you the chance to have some real fun!", objectives = "Kill 12 Clefthoof Bulls and then speak to Hemet Nesingwary at Nesingwary's Safari in Nagrand about your prowess.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9851] = { id = 9851, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clefthoof Mastery", description = "Banthar is the fiercest and most elusive of all the clefthoof in Outland.  She's also the hairiest.\n\nIt is said that she roams with her clefthoof herd in the Spirit Fields near Oshu'gun.\n\nYou want to truly prove your hunting mastery?  Bring me her horn!", progress = "A warm fire and a woman at your side for idle chit-chat is something you can get at home.  Here we hunt big game or die trying.", completion = "You did it!  You took down Banthar!  I never had a doubt, {name}.\n\nHere, I think you've more than earned this.", objectives = "Acquire the Horn of Banthar and return it to Hemet Nesingwary at the Nesingwary Safari in Nagrand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9852] = { id = 9852, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ultimate Bloodsport", description = "The queen of all that dwell in Nagrand is known as Tusker.  She's a giant elekk the likes of which you won't see anywhere else!\n\nYou're right to be fearful of that name.  Bach'lor, Gutripper, and Banthar are nothing when compared to her.  It is said that she can be found on a huge bluff far to the southwest overlooking Oshu'gun.  Bring me her massive heart if you dare.\n\nDo you want to leave a letter with me so that I can have it delivered to your next of kin in the likely event that you don't return?", progress = "There's no shame in admitting that you haven't the spine to hunt the mightiest of animals this land has to offer, {name}.", completion = "{name}!  You bring joy to this old dwarf's heart.\n\nYou have now proven yourself; you've joined the ranks of the elite!  Others ran away in fear, or died, trampled under the foot of the beast.  You used your mind, your cunning, your determination to prove your mastery of the hunt.\n\nTake this and know that you are always welcome to hunt at my side!", objectives = "Bring the Heart of Tusker to Hemet Nesingwary at Nesingwary's Safari in Nagrand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9853] = { id = 9853, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gurok the Usurper", description = "Gurok must be summoned. You summon Gurok and you destroy.\n\nYou must go to Warmaul Hill to the northwest and find where ogre worships Gurok. You put ogre skull from Warmaul ogres on Gurok's earthen brand. Only then will Gurok come. Seven skulls.\n\nIf you live, bring Gordawg back Gurok earthen head. Gordawg crushes head.\n\n<Gordawg bites down hard, shaking the earth beneath your feet.>", progress = "Gordawg eat Gurok power.", completion = "<Gordawg chomps down hard on Gurok's earthen head, nearly disintegrating the stone formation.>\n\nGurok's reign has come to an end. The earthen elements are free. All sleep now. Champion gets reward!", objectives = "Gordawg at the Throne of the Elements in Nagrand has asked that you destroy Gurok the Usurper and bring back Gurok's Earthen Head.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9854] = { id = 9854, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Windroc Mastery", description = "Do you live for the hunt as I do, {class}?  Do you seek the quietude that comes as you stalk your prey?  Would you know what it is to honor the last heartbeats of your fallen quarry?  I will help you to achieve this.\n\nNagrand is a lush land, full of life in the midst of this broken world.  Bring down a handful of the windrocs and then we will speak more.\n\nYou can find them in many places nearby in all directions around our camp.", completion = "Every day is a gift.  Make the most of it.  For tomorrow we shall stride swifter over the plains than today.  We will spread our arms further and strain to achieve that which tonight we can only dream of, though it may ever elude us.", objectives = "Kill 12 Windrocs and then return to Fitz at the Nesingwary Safari in Nagrand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9855] = { id = 9855, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Windroc Mastery", description = "You must always push yourself if you are to one day stalk the mightiest of prey!  While you are not yet ready, I will point you in the right direction.\n\nThere is another breed of windroc even deadlier.  Seek out the ravenous windroc to test your mettle against.  You will find them in the heart of Nagrand to the west and southwest.", completion = "You have proven your skill once more, {class}.  Now you must go on to stalk the fiercest of the windrocs.", objectives = "Hunt down 12 Ravenous Windrocs and then return to Fitz at the Nesingwary Safari in Nagrand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9856] = { id = 9856, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Windroc Mastery", description = "You are ready, {class}.  Ready to face the mother of all windrocs, Gutripper!  Honor demands that after hunting so many of her children that you give her the chance to defeat you!  Seek her out amongst the greater windroc far to the west.\n\nShould you survive, bring her eye to me.", progress = "Have you faced Gutripper yet?", completion = "Her eye looks as if it is still alive.  Do you think that she can still see into your soul?\n\n{name}, you can now count yourself as one of the elite safari hunters.  And you are another step closer to stalking the ultimate prey of this land, Tusker!\n\nYou've earned the right to have this.  May it serve you well.", objectives = "Bring the Eye of Gutripper to Fitz at the Nesingwary Safari in Nagrand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9857] = { id = 9857, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talbuk Mastery", description = "I don't think that I'm up to the hunt today.  Do you think that you might take my place?\n\nI told Hemet that I was going to see about bagging us some of those talbuk that seem to be all over the place.  The stags are especially nice to hunt.  You can find them congregated around the nearby trees.\n\nThink that you could take care of that for me?", completion = "That's a good tale... <cough>...of how you bagged all of those stags, {class}.  But I think that you can do better.  I've got something else in mind for you.", objectives = "Kill 12 Talbuk Stags and then return to Harold Lane at the Nesingwary Safari in Nagrand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9858] = { id = 9858, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talbuk Mastery", description = "This darned scratch is getting the worst of me it would seem.  So, are you up to filling...<cough>... in for me again?\n\nThis time you're going to bag yourself some thorngrazers.  They're tougher and wilier than the stags, so keep your wits about you.  Look for them... <cough>... sheltered under the trees in the middle of Nagrand to the west and south.\n\nGo on, get out there and...<cough>... show Hemet what you're made of.  I'll be fine.", completion = "<cough>, <cough>... {name}!  You did it.  There's only...... one thing left to...... do then.", objectives = "Hunt down 12 Talbuk Thorngrazers and then return to Harold Lane at the Nesingwary Safari in Nagrand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9859] = { id = 9859, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talbuk Mastery", description = "<Wracking cough.>\n\nDon't worry about...<cough>... me.  I'll be fine.  It's just a...<cough>... scratch.\n\nJust the same, I think you'll... <cough>... have to fill in for me one more... <cough>... time.\n\nYou must seek out the great Bach'lor, king of...<cough>... the stags.\n\nBring me one of his hooves...<cough>, <cough>... as confirmation.\n\nLook for him...<cough>... leading his herd in the far west of Nagrand.", progress = "<Harold looks up at you weakly, but manages a smile.>\n\nYou have...<cough>... the hoof?", completion = "Wow!  You did it!  That's really Bach'lor's hoof!\n\nUm, I'm starting to feel much better it would seem.  Here, let me give you something in celebration of your proven hunting prowess!", objectives = "Obtain the Hoof of Bach'lor and return it to Harold Lane at the Nesingwary Safari in Nagrand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9860] = { id = 9860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The New Directive", description = "Return to Cedric at once, {name}.  The aid you've given the Violet Eye will not go unrewarded.\n\nThink what you want of us and our organization, {class}, but gaining the favor of the archmages of Dalaran will not be something you regret.", completion = "Alturus told me all about what happened, {name}.  This is not the end of it, however.  With Karazhan remaining sealed to outsiders, it's only a matter of time until the Legion renews its attacks while we stand powerless in the sidelines.\n\nUnless you accept the responsibility that fate has bestowed upon you, that is.\n\n\n\nWhat do you say, {name}?", objectives = "Speak to Archmage Cedric in the outskirts of Dalaran Crater.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9861] = { id = 9861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Howling Wind", description = "This amorphous mass of elemental air is speaking to you in a language that you cannot understand. You believe the language to be the tongue of the elements: Kalimag. Perhaps someone at the Throne of the Elements could shed some insight on this unusual find.", progress = "Give it here! Quickly!", completion = "It is a distress call, {race}. An outside force is attempting to subvert the elements.", objectives = "Find someone at the Throne of the Elements that knows how to speak Kalimag and show them the Howling Wind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9862] = { id = 9862, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Murkblood Corrupters", description = "Murkblood are capturing and torturing the spirits of air! Murkblood are my kin: A tribe of the Broken who serve the vile Musel'ek, beast lord of Coilfang.\n\nThe air spirit states that the Murkblood putrefiers are capturing other spirits of air and using them to sow chaos into the ranks of the elements. It would seem that the Murkblood have recently sacked an orc village to the southwest known as Sunspring and are using powerful elemental magic to disturb the lake. Find the putrefiers and destroy them.", completion = "You saw them controlling the elements? The wind bent to their will?\n\n<Morgh is lost in thought for a moment.>\n\nThis is troubling, {name}. I must consult with the others.\n\nWe thank you for your efforts, {name}. Perhaps you should return to your village and see if they have any other information about the Murkbloods and their nefarious goals.", objectives = "Elementalist Morgh at the Throne of the Elements in Nagrand wants you to slay 5 Murkblood Putrefiers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9863] = { id = 9863, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vile Idolatry", description = "With our leadership in ruin, we are left open to attacks from all sides. The foul Murkblood tribe could not have picked a better time to attack us!\n\nIn recent days, we have been subject to no less than 5 assaults from the Broken. They have even taken over our only other territorial holding in the area: Sunspring Post.\n\nWe must strike and show them that we are not powerless! Strike down the vile idolaters and bring me their twisted idols of worship so that they may ride the lightning.", progress = "Do this for us because we cannot do it for ourselves.", completion = "You have given the Lightning Sons hope, {name}. If our leader will not protect us, perhaps there are others that are capable - like you.", objectives = "Farseer Kurkush at Garadar in Nagrand wants you to bring him 10 Murkblood Idols.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9864] = { id = 9864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing War Party", description = "After the last Murkblood raid, a group of younglings decided to act. We tried to stop them but the rage had taken hold. It has now been one week since we last saw our beloved younglings.\n\nPlease, {race}, you must find them! They have just barely reached adolescence. How can they expect to defeat such savages?\n\nThey took the road leading west out of town. Follow that road around and look for signs of our younglings.\n\nAnd {name}, avoid Halaa if you value your life. It is a war-zone.", completion = "I have been told stories of my people. They say that once, we were warriors...", objectives = "Try and find the missing Garadar war party.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9865] = { id = 9865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Once Were Warriors", description = "I do not know you, stranger, but I ask for your help. I feel shame for this, but I am only one orc.\n\nEmotions have surfaced that I have never felt. I... I seek vengeance. Blood for blood. Do your people ever feel this? I wish to pick up my axe and split my enemies in two. To swing the weapon until my arms fall lifelessly at my sides, exhausted.\n\nSunspring Post is directly south of this procession. It is there that you will find our enemies... Kill them... Kill them all...", completion = "<Saurfang turns to face you.>\n\nIs it blood that I smell? I regret being unable to lend assistance. How proud you must be. My chest swells just knowing what you have done.\n\nAre there others like you? Where you come from, do more heroes exist?", objectives = "Kill 20 Murkblood Scavengers and 10 Murkblood Raiders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9866] = { id = 9866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "He Will Walk The Earth...", description = "Will you do me one last honor, {name}? I do not wish to return to Garadar. I believe that my destiny lies elsewhere - that I will serve a greater purpose someday.\n\nPlease, return to Farseer Corhuk and tell him that I will not be returning. That I cannot return. I must walk the earth... He will understand.", completion = "<Farseer Corhuk stares at the ground, lost in contemplation. He nods his head affirmatively.>\n\n<Farseer Corhuk wipes a tear away.>\n\nThe son is the father... May the spirits have mercy on those that stand in his way.", objectives = "Deliver the news to Farseer Corhuk at Garadar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9867] = { id = 9867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Murkblood Leaders...", description = "We have lost many friends in recent weeks.\n\nFor decades we have dealt with the ogres of Nagrand but now a new threat has arisen. The Broken tribe of Murkblood attacked our fishing village to the southwest, Sunspring Post, and managed to kill or evict all of the orcs that inhabited the town.\n\nWhile the others feel that the best course of action is to kill indiscriminately, I know that we must destroy their leadership. I do not know who their leader is but I suspect that you will know when you find him.", progress = "Bring me their leader's head, {name}.", completion = "So, this is the face of our enemy? I will have this put upon a pike and placed outside of Garadar, near the gates. Should they think to attack us again, they will see the consequences for their actions looking down upon them...", objectives = "Farseer Margadesh at Garadar in Nagrand wants you to bring him the Head of Ortor of Murkblood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9868] = { id = 9868, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Totem of Kar'dash", description = "Thank you, stranger. They would have surely killed me had it not been for you.\n\nI was kidnapped by these Murkbloods 3 nights ago during a nighttime raid on Garadar. What I have since uncovered may very well shake the foundation of the Outland: these savages seek to recover the totem of Kar'dash! We cannot allow the totem to fall into the hands of the Murkbloods!\n\nYou must help me escape. And stranger, if I do not make it back to Garadar, you must tell Garrosh what happened here...", completion = "What does it matter? The Greatmother is dying. Life is not worth living...", objectives = "Escort the Mag'har Captive out of Sunspring Post. Speak to Garrosh at Garadar if you succeed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9869] = { id = 9869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Throne of the Elements", description = "Greetings, {race}. I am Ioki, elementalist of the Earthen Ring. I have come to Telaar to inform the Kurenai of the state of the elements.\n\nCould I ask a favor of you? Would you travel to the Throne of the Elements in the northern hills of Nagrand, beyond Skysong Lake, and tell elementalist Sharvak that I have arrived at Telaar safely? She will surely reward you for this small deed.", completion = "Ah, thank you for the message. Perhaps you would not mind helping out the Earthen Ring? The elements are in flux. We can use all of the assistance that we can get.", objectives = "Elementalist Ioki wants you to travel to the Throne of the Elements and speak with Elementalist Sharvak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9870] = { id = 9870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Throne of the Elements", description = "Greetings, {race}. I am Yal'hah, elementalist of the Earthen Ring. I have come to Garadar to inform the Mag'har of the state of the elements.\n\nCould I ask a favor of you? Would you travel to the Throne of the Elements in the northern hills of Nagrand, beyond Skysong Lake, and tell elementalist Sharvak that I have arrived at Garadar safely? She will surely reward you for this small deed.", completion = "Ah, thank you for the message. Perhaps you would not mind helping out the Earthen Ring? The elements are in flux. We can use all of the assistance that we can get.", objectives = "Elementalist Yal'hah wants you to travel to the Throne of the Elements and speak with Elementalist Sharvak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9871] = { id = 9871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Murkblood Invaders", description = "The parchment holds a crudely painted map of Nagrand. There is a big red 'X' where Telaar would be on the map. It would seem that these savages are planning an attack on the city. Take the Murkblood invasion plans to Arechron in Telaar.", progress = "What is it?", completion = "<Arechron slams his fist into his hand.>\n\nOrtor... Treacherous fiend!", objectives = "Take the Murkblood Invasion Plans to Arechron at Telaar in Nagrand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9872] = { id = 9872, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Murkblood Invaders", description = "The parchment holds a crudely painted map of Nagrand. There is a big red 'X' where Garadar would be on the map. It would seem that these savages are planning an attack on the city. Take the Murkblood invasion plans to Garrosh in Garadar.", progress = "What is it?", completion = "<Garrosh crumples up the map and throws it into the fire.>\n\nWhat's the use? They've been attacking us for weeks. This is nothing new.\n\nDon't you understand? We're done for... Greatmother Geyah is dying.", objectives = "Take the Murkblood Invasion Plans to Garrosh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9873] = { id = 9873, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ortor My Old Friend...", description = "These invasion plans were written by someone I once knew. Ortor of Murkblood, once a noble Broken, versed in the way of the elements, now a muck addled yes-man of Musel'ek the bog lord.\n\nThe plans state that they have taken over an orc village northwest of here known as Sunspring.\n\nTravel to Sunspring Post and rid the world of Ortor of Murkblood. What you do, you do for the good of us all...", progress = "Remember, {name}, Ortor is a shaman of great power.", completion = "A thousand dead orcs you say? What could have triggered such an audacious advance into orc lands? It is good that he is dead but there is more to this than what meets the tentacle.", objectives = "Arechron at Telaar in Nagrand wants you to kill Ortor of Murkblood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9874] = { id = 9874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stopping the Spread", description = "I have just gotten word of a catastrophe of epic proportions, {name}. The foul Murkblood have sacked the orc village of Sunspring Post, northwest of here, and murdered its residents. To make matters worse, they have begun dumping the bodies into Sunspring Lake. Should those bodies rot, our primary source of water in the region will be compromised.\n\nIt's a gruesome task that I give you next but it must be done. Take this enchanted torch and return to Sunspring. Burn all of the rotting orc corpses...", progress = "The orcs will not understand what we are doing but it must be done. For the good of both orc and Broken.", completion = "<Otonbu sighs.>\n\nThis will set back any chance of peace with the orcs another 10 years. At least we will be around to see those years as opposed to what could have happened had those corpses been allowed to rot.", objectives = "Otonbu the Sage at Telaar in Nagrand wants you to use the Torch of Liquid Fire to destroy 10 Sunspring Villager corpses. Return the Torch of Liquid Fire when the task is complete.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9875] = { id = 9875, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uncatalogued Species", description = "Lauranna must've missed this particular plant.  You're certain you've discovered a species not yet catalogued by Lauranna's work.  You'd best show it to her to see what she makes of it.", progress = "You have something to show me?", completion = "A new species!  Are you sure?\n\n<Lauranna flips through pages of notes and diagrams.>\n\nNice job, {name}.  We'll have to add this one to our list.  How does \"Purple Leafed Aelarathrium\" sound to you?  It does have a ring to it.", objectives = "Bring the Uncatalogued Species to Lauranna Thar'well at the Cenarion Refuge in Zangarmarsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9876] = { id = 9876, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Failed Incursion", description = "I sent a small group of our druids to investigate the drain you discovered inside of Serpent Lake.  They were expected to return shortly after.  Needless to say, they did not.\n\nYou are amongst our most capable allies; I ask you to seek them and find out what became of them.", completion = "Thank Cenarius you showed up.  My injuries prevented me from going back to the outside for help.", objectives = "Ysiel Windsinger wants you to look for signs of Cenarion Expedition Druids near the entrance to Coilfang Reservoir in Zangarmarsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9877] = { id = 9877, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Restorative Draught", description = "The battle against the Scourge is not one without casualties.  Many are slain every day yet many more meet a worse fate.\n\nIt is not uncommon for the Scourge to take prisoners.  Death would be preferable to what awaits them in Deatholme.  They're interrogated and tortured while under the effects of horrible will-breaking poisons.\n\nApothecary Renzithen in Tranquillien has developed a remedy; go to him and retrieve this restorative draught.", completion = "Janeda's sending you to rescue the Deatholme prisoners?  She must think very highly of you, {name}.", objectives = "Speak to Apothecary Renzithen in Tranquillien.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9878] = { id = 9878, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Solving the Problem", description = "The appearance of the Murkblood in Nagrand has had a profound negative impact on our environment. The elementals are all in flux which has, in turn, greatly disturbed the wildlife. Worse yet, the razing of Sunspring Post has reignited the hatred that the orcs held for our people.\n\nWhile the Kurenai are a different tribe than the Murkblood, all an orc sees is Broken.\n\nWe must make an effort to solve this dilemma. Travel to Sunspring Post, northwest of here, and resolve the Murkblood problem.", completion = "It is doubtful that the orcs will understand or appreciate what you just did but Nagrand is better off for the deed. Thank you, problem solver...", objectives = "Poli'lukluk the Wiser at Telaar in Nagrand wants you to kill 10 Murkblood Scavengers and 5 Murkblood Raiders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9879] = { id = 9879, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Totem of Kar'dash", description = "I would have been killed had you not come along, stranger. They have already murdered so many Kurenai in their search for a lost relic.\n\nWhat they seek is the totem of Kar'dash. Why they think that we would know anything about this totem, I cannot understand. Is a totem not an orcish implement by nature?\n\nThis information must be taken back to Arechron. Perhaps he knows why Murkblood are kidnapping Kurenai and torturing them for information regarding an orcish device.\n\nLet's go before more come.", completion = "Yes, I know of the totem... but there is much more to this story. Alas, I lack the authority to reveal this information to you. Only the chosen may be privy to such knowledge.", objectives = "Escort the Kurenai Captive out of Sunspring Post. Speak to Arechron at Telaar if you succeed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9880] = { id = 9880, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hellfire Penninsula: -pn - A - ToWoW - Hellfire Turnin Cap" }
quests[9881] = { id = 9881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hellfire Penninsula: -pn - H - ToWoW - Hellfire Turnin Cap" }
quests[9882] = { id = 9882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealing from Thieves", description = "Nexus Prince Haramad has ordered us to not begin work inside of Oshu'gun as it might anger a certain powerful naaru.  Sort of puts a damper on our operation.\n\nI think I might've found a loophole, however.\n\nYou see, we're not the only ethereals drawn to this colossal diamond.  A thief called Gava'xi has led a band of rogue ethereals into Oshu'gun and they've begun to dislodge large fragments from it.\n\nYour job, {race}, is to go there and retrieve what is rightfully ours.", progress = "Have you retrieved the crystal fragments I asked of you, {name}?", completion = "Color me impressed.  These are in excellent condition, for the most part.\n\nI will make sure to put in a good word for you with our people.", objectives = "Obtain 10 Oshu'gun Crystal Fragments and bring them to Gezhe at Aeris Landing in Nagrand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9883] = { id = 9883, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Crystal Fragments", progress = "You've got more crystal fragments?  Make sure you're not taking any that are still attached to the mountain; we wouldn't want to stir up trouble with the naaru.", completion = "Keep the crystal fragments coming, {name}.  We cannot let these thieves take our property.\n\nEven if it's not ours just quite yet.  A technicality, of course." }
quests[9884] = { id = 9884, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Membership Benefits", objectives = "The Consortium is well known for taking good care of its friends. At the beginning of each month I'll have some gems ready for you as payment for your services.\n\nThe quality of the gems you get will depend on how loyal you've been to us. Here's to hoping you do the smart thing and stay with us.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9885] = { id = 9885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Membership Benefits", objectives = "The Consortium is well known for taking good care of its friends. At the beginning of each month I'll have some gems ready for you as payment for your services.\n\nThe quality of the gems you get will depend on how loyal you've been to us. Here's to hoping you do the smart thing and stay with us.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9886] = { id = 9886, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Membership Benefits", objectives = "The Consortium is well known for taking good care of its friends. At the beginning of each month I'll have some gems ready for you as payment for your services.\n\nThe quality of the gems you get will depend on how loyal you've been to us. Here's to hoping you do the smart thing and stay with us.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9887] = { id = 9887, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Membership Benefits", objectives = "The Consortium is well known for taking good care of its friends. At the beginning of each month I'll have some gems ready for you as payment for your services.\n\nThe quality of the gems you get will depend on how loyal you've been to us. Here's to hoping you do the smart thing and stay with us.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9888] = { id = 9888, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Impotent Leader", description = "I have escaped certain death, surviving a cowardly nighttime attack by Boulderfist ogres upon my village.\n\nBut I ask you, stranger: For what?\n\n<Jorin points to Garrosh.>\n\nHe has refused to give us assistance. Ogres are rampaging through my town and he sits here, weeping into a fire. What has become of us? What will become of us?\n\nI've sent a scout, Kilrath, to the village, now the Bleeding Hollow Ruins. Will you find him and give him your assistance? He hides on the border of Nagrand and Terokkar.", completion = "<Kilrath speaks in a hushed tone.>\n\nThese ogres are extremely peculiar. They are also extremely stupid. Look how the fat one makes the, um, lesser fat ones dance. It's mesmerizing.", objectives = "Jorin Deadeye has asked that you find and speak with Kilrath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9889] = { id = 9889, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Don't Kill the Fat One", description = "I have been watching these beasts for days. The fat one says that he is waiting for something. What he is waiting for, however, is a mystery.\n\nI have a plan but it is going to involve some violence on your part. You will need to kill several of his subordinates and then beat him within an inch of his life. Do this and I am certain he will tell us everything that we need to know.", progress = "I submit! I submit!", completion = "Let me live and I'll tell you whatever you want to know!", objectives = "Kilrath in Terokkar Forest has asked that you kill 10 Boulderfist Invaders and beat Unkor the Ruthless until he talks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9890] = { id = 9890, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Success!", description = "For many years, Boulderfist ruled all ogres in the Outland. The ogres were united under Krol and content with the lands that they were given. In the past few months, we have lost many ogres to a new clan known as Warmaul. Warmaul has taken most of our land in Nagrand and killed many of our people.\n\nWe had no choice but to take this town. We are being exterminated...\n\nKrol has gone missing and Boulderfist is in turmoil. Lantresor of the Blade rules in his absence.", completion = "Slow down, {name}. I am but a lowly rogue. I have no idea what to do with such information.", objectives = "Take the information that you beat out of Unkor back to Kilrath in Terokkar Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9891] = { id = 9891, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Because Kilrath is a Coward", description = "Take what you have learned and tell Jorin at Garadar. I can assure you that he won't be happy to know that our village was destroyed and many of our people killed because the ogres needed more space.\n\nMay the ancestors watch over you... I will be hiding in the bushes if you need me for anything else.", completion = "So they think that they are within their rights to displace and slaughter orcs on a whim, eh? I'm sure that this had nothing to do with our leader being an impotent whelp... If only he'd gotten a fraction of the passion that his father had...", objectives = "Take the information that you beat out of Unkor to Jorin Deadeye at Garadar in Nagrand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9892] = { id = 9892, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Obsidian Warbeads", progress = "Have you obtained any more warbeads?  You'll find plenty of ogres to the far north, near the border with Zangarmarsh.", completion = "We'll make a good profit on these, {name}.  I'll make sure Khoraazi hears about your work here." }
quests[9893] = { id = 9893, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Obsidian Warbeads", description = "All this waiting around for Oshu'gun to be ready for digging is eating into our profits, {name}.\n\nFortunately, I've devised an alternate source of income.  The ogres of Nagrand wear warbeads made of obsidian, a mineral that commands a hefty price in many other worlds.\n\nZerid already has had to take care a few of the brutes as a matter of security.  Think of the warbeads as an added bonus.  Or better yet, don't think about it too much and just bring them to me.", progress = "How are those ogres treating you, {name}?  Tough bunch, aren't they?", completion = "Excellent.  This will keep us in business while we wait for the Sha'tar to finish whatever housekeeping it is they need to do inside Oshu'gun.", objectives = "Bring 10 Obsidian Warbeads to Gezhe at Aeris Landing in Nagrand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9894] = { id = 9894, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Safeguarding the Watchers", description = "In your travels, you might have encountered some of the expedition's watchers. They do the majority of the field work: documenting the unique inhabitants of the marsh, collecting samples, and making contact with sentient species.\n\nThe safety of the watchers is paramount, {class}. We've had to recall the watchers we sent to explore Funggor Cavern to the south, because of marshbeast attacks. Warden Hamoot believes that killing their leader, Lord Klaq, will bring a swift end to the attacks.", progress = "Have you located and dealt with Lord Klaq?", completion = "You have my gratitude, {name}, and that of the watchers. They will be heartened to hear that they can continue their work to the south without fear of attack.", objectives = "Kill Lord Klaq and return to Windcaller Blackhoof at the Cenarion Refuge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9895] = { id = 9895, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dying Balance", description = "Have you observed your surroundings closely, {name}? This is an ailing landscape, struggling to keep itself in balance and losing the fight.\n\nIf you know where to look, you can see the symptoms. Members of some species rapidly outgrow their peers and become more aggressive.\n\nA good example of this uncontrolled growth is the marshtrekker Boglash. If you wish to see it for yourself, look no further than the waterways south of the refuge.\n\nBe prepared to defend yourself. The creature knows no mercy.", progress = "Have you encountered Boglash?", completion = "Now that you've seen the symptoms of imbalance with your own eyes, be mindful of them in your travels.", objectives = "Locate and deal with Boglash, then return to Lethyn Moonfire at Cenarion Refuge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9896] = { id = 9896, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blacksting's Bane", description = "By Khaz'goroth's flaming navel, it's hot here! I can't blame the first party for leaving, but everyone knows 'twasn't the heat that drove them away. No, it was Blacksting, although they won't admit it.\n\nThey were camped just to the south of the glowing draenei towers to the west, just north of the Feralfen Village, when the giant wasp appears out of nowhere and attacks! I can't wait to see the looks on their faces when I bring the creature's stinger back to Ironforge and show it to them!", progress = "Did you manage to get the stinger? Remember, it's useless to me if it's damaged.", completion = "I can't thank you enough, lad. I'm going to enjoy this...", objectives = "Bring Blacksting's Stinger to Prospector Conall at Telredor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9897] = { id = 9897, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I'm Saved!", description = "I don't mind sharing.  I'm just glad to be saved from that creep, Gankly!  And I collected tons of skins from Zangarmarsh, so it's no problem at all!", progress = "Kristen is a very nice...<cough>... person to share her skins, wouldn't you agree?", completion = "Well, I couldn't see if you helped out with saving Kristen, or not.  But if she handed you one of her bundles of skins then you're alright in my book.\n\nHere's your reward.", objectives = "Give the Bundle of Skins to Harold Lane at the Nesingwary Safari in Nagrand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9898] = { id = 9898, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Respect of Another", description = "Magasha is the fiercest troll in the Marsh, but she only respects mighty hunters. \n\nI tried to prove myself to her, but the one beast that could impress her is beyond my skill. Maybe you could help me out? It's the giant bog wasp known as Blacksting that roams the area south of the glowing draenei towers to the west. If you bring me its stinger maybe she'll give me a chance to join her hunters.\n\nI know it's a little sneaky, but I promise to learn under her and do ya both proud.", progress = "My luck is about to change - I can feel it.", completion = "Fantastic! I'll never forget how you helped me to win her heart. In fact, you can be a guest of honor at our wedding.", objectives = "Bring Blacksting's Stinger to Reavij at Swamprat Post.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9899] = { id = 9899, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Job Undone", description = "Someone needs to find a way to make Reavij come to his senses! He's ignoring his duty and instead, he's devoting all his energy to getting my attention. I've tried ignoring him and telling him to stop. Nothing seems to work.\n\nUntil he gets over this, I'm left cleaning up after him. He was supposed to have dealt with Sporewing, but I'll bet the monster is alive and well. If you have time, would you mind going to the western part of the Dead Mire and killing the bat? I'll deal with Reavij in the meantime.", completion = "At least someone is pulling his weight around here. Thank you for taking care of that matter, {name}. I need to have a word with Zurai about Reavij. His scheming and daydreaming have gone on long enough.", objectives = "Magasha at Swamprat Post wants you to kill Sporewing.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9900] = { id = 9900, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gava'xi", description = "The presence of rogue ethereals in this area might amuse Gezhe, who sees nothing but opportunity wherever we go, but it's a true threat to the security of our operations.\n\nTheir leader, Gava'xi, is a dangerous criminal and I've made it my top priority to see to it that he is neutralized.\n\nIf you're looking to make yourself useful, go and take care of Gava'xi.  I will see to it that you're rewarded properly.", completion = "We won't have to worry about Gava'xi anymore, thanks to you.  Let us arrange for your reward now.", objectives = "Slay Gava'xi near Oshu'gun and return to Zerid at Aeris Landing in Nagrand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9901] = { id = 9901, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unfinished Business", description = "The first expedition the league sent reported encountering a gigantic spore bat they'd taken to calling Sporewing. They had to leave in a hurry, so they didn't have the chance to kill him while they were here, so I figured I'd finish the job for them.\n\nWhat's left of their report suggests that the creature can be found in the southwestern parts of the Dead Mire. I think Vindicator Idaar mentioned that it's to the northeast of Telredor.", completion = "Well done, {name}. I think you and I have managed to outshine a whole team of prospectors. When I get back to Ironforge, I'm sure I'll get my choice of assignments.", objectives = "Prospector Conall at Telredor wants you to kill Sporewing.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9902] = { id = 9902, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Terror of Marshlight Lake", description = "Traveling through naga-infested lands has shown me the cruel truth about how my less fortunate brethren are treated. At Marshlight Lake, to the southwest, I observed a particularly malicious taskmaster playing a deadly game. He orders his slaves out to the islands in Marshlight Lake when he knows that Terrorclaw, a giant bogstrok, is ready to feed.\n\nI needn't describe what results. We are too few to take on the naga directly, but we can deprive them of their amusement by killing their pet.", completion = "Thank you, {name}. Perhaps with the help of the draenei, this marsh will one day be free of naga. I can't imagine what it must be like to be forced to serve them.\n\nHe doesn't talk about it often, but Maktu was once a slave.", objectives = "Slay Terrorclaw and return to Puluu at the Orebor Harborage.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9903] = { id = 9903, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Biggest of Them All", description = "You've dealt with most of the little hydra, but I doubt Mragesh was impressed by your display. He's a cunning, ferocious beast and he's dogged many an angler in his time.\n\nI intend to be the last one he'll ever bother. He's bound to be hiding deep in the waters of Serpent Lake, to the northeast. He's a has-been; he just doesn't know it yet.", completion = "I'm sure the old boy must've seen his days coming to an end. With all these new arrivals, the old order couldn't stand. It's just as well his spirit is at rest now.", objectives = "Slay Mragesh and return to Zurjaya in Zabra'jin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9904] = { id = 9904, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pursuing Terrorclaw", description = "I've caught every kind of fish that lives in the marsh, but there's one that eludes me. Sure, I've caught eels and mudfin frenzies. But the last time I was out on one of the islands in Marshlight Lake, I hooked a gigantic bogstrok that snapped my line and got away.\n\nTerrorclaw, he's called, and I won't rest until he's dead. He's too big for any fisherman to catch, so I suppose we'll just have to kill him the old-fashioned way.", completion = "At last! They say every great fisherman has a story of \"the one that got away,\" but I haven't yet met a creature I couldn't beat one way or another.", objectives = "Kill Terrorclaw and return to Zurjaya at Zabra'jin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9905] = { id = 9905, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maktu's Revenge", description = "Last time Maktu was out hunting hydras for hides at Serpent Lake, he was attacked by the biggest hydra he's ever seen. Maktu reached for his spear, but it was too late. He had just enough time to escape becoming hydra food.\n\nWho knows? Maybe next time, Maktu not be so lucky. Maktu wants to be there so there won't be a next time. Will you help Maktu get his revenge on Mragesh?", completion = "<Maktu nods approvingly.>\n\nMaktu is thankful for your help. Maktu's pride is satisfied. He will not be caught off guard again.", objectives = "Locate and kill Mragesh, then return to Maktu at the Orebor Harborage.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9906] = { id = 9906, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Message in a Battle", description = "Ogres are moved by one thing: Might. If we expose ourselves to them as being weak, they will take advantage of that weakness and wipe us out.\n\nGarrosh might be ready to lie down and let the ogre dogs take our lands but I am not! I need you to deliver a message to the Boulderfist, {name}. The only type of message that they are capable of understanding: Brutality.\n\nTravel to the Burning Blade Ruins, southeast of here and show them the might of the Mag'har.\n\nAnd {name}, check in with the others before leaving.", completion = "Our task is not yet finished. There are more that must be taught a lesson!", objectives = "Jorin Deadeye at Garadar in Nagrand has asked that you slay 8 Boulderfist Crushers and 8 Boulderfist Mystics.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9907] = { id = 9907, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Audacious Advance", description = "Directly west of here you will find the Halaani Basin. Within the basin are the twin clefts of Nagrand: Northwind and Southwind. Boulderfist shock troops use the clefts to hide their ogre mounds.\n\nI need you to track down those troops and kill all that you encounter in the name of Mag'har.", completion = "If this does not freeze the blood in their veins, nothing will. You have done the Mag'har justice, {name}. And for justice, Mag'har rewards greatly.", objectives = "Jorin Deadeye at Garadar in Nagrand has asked that you slay 10 Boulderfist Warriors and 10 Boulderfist Mages.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9908] = { id = 9908, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hellfire Penninsula: -pn - A - ToWoW - Hellfire Turnin" }
quests[9909] = { id = 9909, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hellfire Penninsula: -pn - H - ToWoW - Hellfire Turnin" }
quests[9910] = { id = 9910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Standards and Practices", description = "If you're venturing into the Burning Blade Ruins, I have a task for you. Take these Mag'har battle standards and place them at three distinct locations in the ogre compound. An area of high visibility is recommended. Look for the gigantic flaming pyres on the upper levels. Place a standard near the first, second, and third Burning Blade pyres.\n\nThe standard will leave a lasting impression upon any ogres who may have missed the battle.", progress = "Respect from fear! It is as good as any other kind.", completion = "Perhaps you would like another task? A more delicate matter, eh?", objectives = "Elkay'gan the Mystic at Garadar in Nagrand wants you to use the Mag'har Battle Standard at the First Burning Blade Pyre, Second Burning Blade Pyre, and Third Burning Blade Pyre. Return the left-over Mag'har Battle Standards to him when you are finished.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9911] = { id = 9911, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Count of the Marshes", description = "This bloody mandible comes from an unbelievably large creature. The nether ray that it belonged to has to be the largest ever seen in Zangarmarsh. Judging from the condition of the mandible, the count must've abandoned a diet of carrion in favor of living flesh.\n\nSurely the Cenarion Expedition would be interested in such a specimen. Watcher Leesa'oh has a small camp to the west of Quagg Ridge.", progress = "<The watcher blinks several times in surprise.>\n\nWhere did you get that... thing?", completion = "Are you sure that's real? I mean, I knew there was large wildlife in the marsh, but there are giant creatures and then there are GIANT bugs.\n\nCome to think of it, the sporelings did mention a story about a fearsome nether ray that used to terrorize them before the boglord incursion.\n\nWhat if the stories are true? Oh, dear. I'd better take that for safekeeping. The expedition will want to know about this.", objectives = "Bring \"Count\" Ungula's Mandible to Watcher Leesa'oh at the Cenarion Outpost in Zangarmarsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9912] = { id = 9912, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cenarion Expedition", description = "The Cenarion Circle's main expeditionary force in Outland is known as the Cenarion Expedition.  Though it began as a small venture controlled directly by the Cenarion Circle, it's become a large and fairly autonomous body.\n\nThe expedition's leader, Ysiel Windsinger, has asked us to direct volunteers to her outpost.  Report to her at the Cenarion Refuge in eastern Zangarmarsh.  Take the main path to the west and it will lead you directly there.", completion = "Welcome to Cenarion Refuge, {name}.  I hope you've come to aid us in our mission.  We've much work ahead of us.", objectives = "Speak to Ysiel Windsinger at the Cenarion Refuge in Zangarmarsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9913] = { id = 9913, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Consortium Needs You!", description = "My organization, the Consortium, is looking for a few resourceful individuals just like yourself.  You'll be hard pressed to find ethereals more honest, hard-working or pleasant to be around than us.\n\nAll we require is loyalty, dedication and a reasonable amount of moral flexibility.  If you're interested, speak to Gezhe, our ground operations leader.  You will find him at Aeris Landing, north of Oshu'gun.", completion = "Are you ready to get to work, {race}?  I think I've got the perfect task for you.", objectives = "Report to Gezhe at Aeris Landing in Nagrand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9914] = { id = 9914, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Head Full of Ivory", description = "Ivory is a much sought after prize.  I have many customers lined up in far off places to purchase it.\n\nI could be convinced to let you in on a cut of the profits.\n\nThe wild elekk roaming Nagrand have the high quality of tusks that I'm after.  Steer clear of the bull elekk; their ivory isn't in the condition that I desire.\n\nOh and don't worry, it's not poaching; I have an understanding with both the orcs and the draenei.\n\nDo you and I have an understanding?", progress = "It's ivory that I'm after, not excuses.  Of course, if you'd rather, we can renegotiate your percentage of the profits.  I doubt that you'd be pleased with the result.", completion = "Never doubted you for a second, friend.  Most of those look like fine specimens, if a bit dirty and scratched up.  Still, I think they're worth the value we agreed upon previously.\n\nI hope that we can continue to do business in the future.", objectives = "Collect 3 Pair of Ivory Tusks and return them to Shadrek at Aeris Landing in Nagrand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9915] = { id = 9915, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Heads Full of Ivory", progress = "I still have a need for more pairs of ivory tusks from the wild elekk that roam this land.  Unfortunately, my budget will no longer handle your cut of the profits.  If you continue to provide me what I need, however, you will be ingratiating yourself with the Consortium.", completion = "Excellent, more fine tusk specimens, though some look a bit dingy.\n\nYou have the far-reaching gratitude of the Consortium, {name}." }
quests[9916] = { id = 9916, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bleeding Hollow Supply Crates", description = "The Boulderfist have moved the supplies they stole from our village to the twin clefts of Nagrand, found west of here in the Halaani Basin.\n\nWhile you are in the area, keep your eye out for the supply crates. If we can get those back, it would ease much of the burden that has fallen upon the matrons of Garadar.", progress = "The children might be able to go a day without feeling hunger pangs.", completion = "Most of our possessions were destroyed or stolen in the attacks. I cannot offer you much, but there are some items that you may find useful...", objectives = "Elkay'gan the Mystic at Garadar in Nagrand wants you to recover 10 Bleeding Hollow Supply Crates.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9917] = { id = 9917, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Do My Eyes Deceive Me", description = "Do my eyes deceive me or is there an ogre hunting party over yonder? What could ogres be doing this far from their mound? I don't like this one bit, stranger. First Murkbloods and now ogres. We just don't have the manpower to handle all of these threats to our land.\n\nCould you investigate the ogre presence to the east for us? Their forward camp is about 200 paces east of here. You'll know you're at the right place if you see the Boulderfist hunters. Kill them to find the plans!", progress = "Have you found any new information?", completion = "<Bintook reads the plans.>\n\nBY THE LIGHT! Their penmanship is atrocious. From what I can gather, they're either planning to \"eat the blue skins and take their village\" or bake a blueberry pie. It really could go either way. We must get to the bottom of this!", objectives = "Huntress Bintook at Telaar in Nagrand wants you to recover Boulderfist Plans.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9918] = { id = 9918, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not On My Watch!", description = "The battle plans were written up by an ogre lieutenant. His name is either Dump or Lump.\n\n<Bintook turns the parchment sideways and cocks her head.>\n\nIt could also be Billy.\n\nAnyhow, I think you should go back out there and have a word with Billy or Lump or Dumpy or whatever! Try to approach him diplomatically. If that doesn't work, try using some muscle.", completion = "Oh my! This is a small scouting and hunting party? You must tell Mo'mor what you have discovered.", objectives = "Huntress Bintook at Telaar in Nagrand wants you to speak to Lump. Return to Huntress Bintook when you have gathered the information that she requested.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9919] = { id = 9919, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sporeggar", description = "You're a kind {race}, {name}.  Not like some of the others I've met.\n\nYou should meet the rest of my people; they'll be very grateful for your help.  Take these spore sacs to my leader, Msshi'fn.  You will find him in Sporeggar, north of here.", progress = "You've something to show me, {name}?", completion = "You've helped protect the next generation of sporelings, {race}.  We can only repay you by welcoming you into our homes.  Stay for a bit and meet the other sporelings.  They will have many questions, I hope you don't mind.", objectives = "Go to Sporeggar in Zangarmarsh, north of the Spawning Glen, and deliver the Salvaged Spore Sacs to Msshi'fn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9920] = { id = 9920, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mo'mor the Breaker", description = "You must seek out Mo'mor immediately! You will find him in the center of Telaar, by the fountain. Tell him exactly what the ogre told you.", completion = "<Mo'mor looks perplexed.>\n\nSo, a new tribe of ogres is forcing the Boulderfist further and further south. This is quite troubling. We must first deal with the situation closest to home...", objectives = "Huntress Bintook at Telaar in Nagrand wants you to speak to Mo'mor the Breaker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9921] = { id = 9921, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ruins of Burning Blade", description = "These ogre hunting parties are a precursor to invasion. We must strike at them before they have a chance to amass an army big enough to take over our town.\n\nYou're going to need to get your hands dirty, {race}.\n\nThe largest collection of Boulderfist in this region can be found at the Burning Blade Ruins, almost directly east of Telaar, near the border of Terokkar. Go there and show the Boulderfist that Telaar will not bend to their will!", completion = "Excellent. Did you happen to locate this Lantresor creature that the stupid one's letter mentioned?\n\nRegardless, we must press on. I have gotten reports of more ogre activity that must be dealt with at once!", objectives = "Mo'mor the Breaker at Telaar in Nagrand wants you to kill 8 Boulderfist Crushers and 8 Boulderfist Mystics.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9922] = { id = 9922, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Twin Clefts of Nagrand", description = "You made a strong showing, {name}. Are you ready for more?\n\nI have received reports of a large contingent of Boulderfist ogres hidden in the twin clefts of Nagrand, northwest of here in the Halaani Basin.\n\nVenture forth to the clefts and deal with the remaining Boulderfist ogres.", completion = "Excellent work! I am currently researching the Warmaul tribe that the Boulderfist lieutenant mentioned. Now the tasks you have performed must be tested.", objectives = "Mo'mor the Breaker at Telaar in Nagrand has asked that you slay 10 Boulderfist Warriors and 10 Boulderfist Mages.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9923] = { id = 9923, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "HELP!", description = "HELP! They're gonna eat me! I just know it!\n\nFind the key, I know it has to be on one of these ogres.\n\nIf you get me out of here, my father will reward you handsomely! He's the leader of Telaar, Arechron.", completion = "I'm really sorry about this, {race}. He's always getting himself into trouble. I just wish I could put a leash on him...", objectives = "Find the Boulderfist Key and Free Corki. Speak with Arechron in Telaar should you succeed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9924] = { id = 9924, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corki's Gone Missing Again!", description = "<Arechron sighs.>\n\nThis is so embarrassing. Do you remember my boy, Corki? You rescued him from the Burning Blade Ruins recently. Well, his curiosity has gotten the best of him once more. He told me that he was going to investigate the Boulderfist menace for 'uncle' Mo'mor and ran off to the ogre mounds in the Halaani Basin, north of here.\n\nDo you think you could track him down? I would be eternally grateful.", completion = "Thank you so much, {name}. His mother will deal with him from now on.", objectives = "Arechron at Telaar has asked that you find and free Corki.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9925] = { id = 9925, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Matters of Security", description = "Gezhe chose to base our operations as close to Oshu'gun as possible, without any regard for the safety of our crew.  Why?  Because he projected a ten percent increase in productivity by setting up shop here instead of in the mountains to the south.\n\nNever mind the crazed voidspawn wandering all of ten feet away from us.  That would be the security officer's problem, not Gezhe's.\n\nKill some voidspawn for me and I'll pay you a tenth of our security budget.  Don't get excited, it's not much of a budget.", completion = "You bring a smile to my face, {name}.  Or you would, rather, if I had a face.\n\nKeep it up and you and I are going to be the best of friends.", objectives = "Zerid at Aeris Landing in Nagrand wants you to kill 8 Voidspawn near Oshu'gun.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9926] = { id = 9926, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG Shadow Council/Warmaul Questline" }
quests[9927] = { id = 9927, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruthless Cunning", description = "<Lantresor hands you a pack full of banners.>\n\nThese are Warmaul ogre banners that I recently acquired.\n\nI want you to travel to Kil'sorrow Fortress, directly south of here, and kill as many of the Kil'sorrow filth as you can find. Drive a Warmaul ogre banner through the heart of each fallen Kil'sorrow soldier. Return to me when you have completed this task and the other that this plan requires.", progress = "<Lantresor's eyes open in bewilderment.>\n\nIs it done?", completion = "Can you imagine their puzzlement over what is happening, {race}? This will be glorious.", objectives = "Lantresor of the Blade at the Burning Blade Ruins in Nagrand wants you to drive 10 Warmaul Ogre Banners through the bodies of Kil'sorrow members at Kil'sorrow Fortress.\n\nReturn any unused Warmaul Ogre Banners.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9928] = { id = 9928, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Armaments for Deception", description = "You will need to steal Kil'sorrow armaments from Kil'sorrow Fortress if my plan is to work.\n\nSearch the fortress for crates of Kil'sorrow armaments. Bring whatever you can find to me.\n\nKil'sorrow Fortress is located directly south and a little to the west of the Burning Blade Ruins.", progress = "We will ignite a hatred heretofore unseen between the two clans!", completion = "Excellent! Our next target will be the Laughing Skull Ruins.", objectives = "Lantresor of the Blade at the Burning Blade Ruins in Nagrand wants you to collect 10 Kil'sorrow Armaments.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9929] = { id = 9929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Merchant", description = "I don't suppose you've been here long enough to know Dugar, have you? He's a merchant with contacts among the various factions in Shattrath.\n\nDon't ask me how he does it, but he manages to trade with them for some of the goods our quartermasters can't provide.\n\nHe set out for Shattrath three days ago and hasn't returned. He's normally able to make the entire trip in less than that. If you're going to be traveling in the forest, would you keep an eye out for him?", sourceObjective = "Travel northwest along the road toward Shattrath and search for evidence of what happened to Dugar.", sourceObjectiveStatus = "unverified-source-field" }
quests[9930] = { id = 9930, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Merchant", description = "I don't suppose you've been here long enough to know Deirom, have you? He's a merchant with contacts among the various factions in Shattrath.\n\nDon't ask me how he does it, but he manages to trade with them for some of the goods our quartermasters can't provide.\n\nHe set out for Shattrath three days ago and hasn't returned. He's normally able to make the entire trip in less than that. Keep an eye out for him and report anything you find to the mercenary captain, Thander.", sourceObjective = "Travel northwest along the road toward Shattrath and search for evidence of what happened to Deirom.", sourceObjectiveStatus = "unverified-source-field" }
quests[9931] = { id = 9931, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Returning the Favor", description = "Now you must plant the seed of war in the fat, useless heads of the Warmaul. To the northwest, near the mountains, you will find the Laughing Skull Ruins.\n\n<Lantresor points into the crate of armaments you brought him.>\n\nDo you recognize those banners? They are Kil'sorrow banners. I want you to take a stack of Kil'sorrow banners and plant them on the corpses of Warmaul ogres. Remember, northwest is where you will find the ogres.", progress = "Can you predict what will happen next?", completion = "The plan is perfect, {name}. I am already seeing the fruits of your labor.", objectives = "Lantresor of the Blade at the Burning Blade Ruins in Nagrand wants you to drive 10 Kil'sorrow Banners through the bodies of Warmaul ogres at the Laughing Skull Ruins.\n\nReturn any unused Kil'sorrow Banners.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9932] = { id = 9932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Body of Evidence", description = "Your rampage through Kil'sorrow Fortress has provided us with a special opportunity. We have enough bodies to make it appear as if a great battle has taken place.\n\nTravel to the Laughing Skull Ruins and find the Laughing Skull Courtyard. There should be a blazing pyre in the courtyard. Make sure the area is secure and then use this blanket to send up smoke signals. When my ogres see the smoke, they will sneak in and plant the bodies of slain Kil'sorrow soldiers.\n\nThat should be the final straw!", progress = "Do you now understand why you could never win a war against me?", completion = "I must admit, I have not felt this alive in decades. You have performed well, {name}.", objectives = "Lantresor of the Blade at the Burning Blade Ruins in Nagrand wants you to use the Damp Woolen Blanket at the Blazing Warmaul Pyre in the Laughing Skull Courtyard to signal his ogres.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9933] = { id = 9933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Message to Telaar", description = "<Lantresor points to an unmarked crate.>\n\nTake it. It is my offering to your people. You have single-handedly saved my clan from extermination.\n\nYou may tell your leader that Lantresor of the Burning Blade and his Boulderfist ogres accept the offering of peace.\n\n<Lantresor bows.>", progress = "Peace you say?", completion = "Please, {name}, take from the peace offering whatever it is that you may desire. After all, without your efforts, this would not have been possible.", objectives = "Take the Burning Blade Peace Offering to Arechron at Telaar in Nagrand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9934] = { id = 9934, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Message to Garadar", description = "<Lantresor points to an unmarked crate.>\n\nTake it. It is my offering to your people. You have single-handedly saved my clan from extermination.\n\nYou may tell your leader that Lantresor of the Burning Blade and his Boulderfist ogres accept the offering of peace.\n\n<Lantresor bows.>", progress = "<Garrosh seems unmoved by the offering.>", completion = "<Garrosh kicks the crate aside.>\n\nYou waste your time, {race}. Take whatever you desire from the crate. I nor Garadar have any need for these useless trinkets.", objectives = "Take the Burning Blade Peace Offering to Garrosh at Garadar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9935] = { id = 9935, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Giselda the Crone", description = "Wanted: Dead or Alive\n\nGiselda the Crone of Kil'sorrow and her lackeys for murder, ritual sacrifice, communing with the Legion, kidnapping, and burglary.\n\nKnown to congregate at Kil'sorrow Fortress in southeastern Nagrand, near the border of Terokkar.\n\nLarge gold reward to be dispensed by Warden Bullrok at Garadar to anyone able to bring Giselda to justice.", completion = "The crone has been slain! This is wonderful news, {name}. Here is your reward.", objectives = "Slay Giselda the Crone and any combination of 10 Kil'sorrow Agents. Return to Warden Bullrok at Garadar should you complete this task.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9936] = { id = 9936, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Giselda the Crone", description = "Wanted: Dead or Alive\n\nGiselda the Crone of Kil'sorrow and her lackeys for murder, ritual sacrifice, communing with the Legion, kidnapping, and burglary.\n\nKnown to congregate at Kil'sorrow Fortress in southeastern Nagrand, near the border of Terokkar.\n\nLarge gold reward to be dispensed by Warden Moi'bff Jill at Telaar to anyone able to bring Giselda to justice.", completion = "The crone has been slain! This is wonderful news, {name}. Here is your reward.", objectives = "Slay Giselda the Crone and any combination of 10 Kil'sorrow Agents. Return to Warden Moi'bff Jill at Telaar should you complete this task.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9937] = { id = 9937, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Durn the Hungerer", description = "You have destroyed two of the biggest threats in Nagrand, {name}. Are you ready to take on the scourge of the Spirit Fields?\n\nDurn the Hungerer lords over the area surrounding Oshu'gun, decimating all in his path. Thus far, none have been able to rid Nagrand of this ferocious gronn. Venture to the Spirit Fields, far southwest of here, near Oshu'gun, and track down Durn. Slay him and I assure you rewards commensurate with the difficulty of the task at hand.", completion = "Durn's murderous grip has been loosed! Nagrand has a brighter tomorrow because of you, hero. Well done!", objectives = "Slay Durn the Hungerer. Return to Warden Bullrok if you manage to complete this task.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9938] = { id = 9938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Durn the Hungerer", description = "You have destroyed two of the biggest threats in Nagrand, {name}. Are you ready to take on the scourge of the Spirit Fields?\n\nDurn the Hungerer lords over the area surrounding Oshu'gun, decimating all in his path. Thus far, none have been able to rid Nagrand of this ferocious gronn. Venture to the Spirit Fields, west of here, and track down Durn. Slay him and I assure you rewards commensurate with the difficulty of the task at hand.", completion = "Durn's murderous grip has been loosed! Nagrand has a brighter tomorrow because of you, hero. Well done!", objectives = "Slay Durn the Hungerer. Return to Warden Moi'bff Jill if you manage to complete this task.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9939] = { id = 9939, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Zorbo the Advisor", description = "Wanted: Dead or Alive\n\nZorbo the Advisor, wanted for numerous planned attacks on Garadar. Along with his reavers and shaman, Zorbo has slain countless orcs. Consider Zorbo as armed, dangerous, and merciless.\n\nZorbo makes his home in the Laughing Skull Ruins in the northern mountains of Nagrand.\n\nReward for Zorbo the Advisor's death or capture to be dispensed by Warden Bullrok at Garadar.", completion = "This is a great victory for the people of Garadar! Well done, {name}!", objectives = "Slay Zorbo the Advisor, 5 Warmaul Shaman and 5 Warmaul Reavers. Return to Warden Bullrok if you manage to complete this task.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9940] = { id = 9940, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Zorbo the Advisor", description = "Wanted: Dead or Alive\n\nZorbo the Advisor, wanted for numerous planned attacks on Telaar. Along with his reavers and shaman, Zorbo has slain countless Broken. Consider Zorbo as armed, dangerous, and merciless.\n\nZorbo makes his home in the Laughing Skull Ruins in the northern mountains of Nagrand.\n\nReward for Zorbo the Advisor's death or capture to be dispensed by Warden Moi'bff Jill at Telaar.", completion = "This is a great victory for the people of Telaar! Well done, {name}!", objectives = "Slay Zorbo the Advisor, 5 Warmaul Shaman and 5 Warmaul Reavers. Return to Warden Moi'bff Jill if you manage to complete this task.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9941] = { id = 9941, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Down the Culprits", description = "The arakkoa tracks, accompanied by a pair of shallow ruts, lead north across the road. It seems the arakkoa dragged something away from the site of the battle, perhaps toward a nearby settlement.\n\nWhile the broken cart shows signs of a struggle, there's little information about Deirom's fate. Follow the arakkoa tracks north and continue your search for the merchant. If he was captured alive, there may still be a chance to rescue him.", sourceObjective = "Continue your search for signs of Deirom in the Arakkoa settlement north of the broken cart.", sourceObjectiveStatus = "unverified-source-field" }
